(function () {
  'use strict';
  const F = FG, C = ['#9fe6bf','#8dc9ff','#d9b2ff','#ffc48d','#ffe58b','#a5dcff'];
  const clamp = (v,a,b)=>Math.max(a,Math.min(b,v)), R=(a,b)=>a+Math.random()*(b-a);
  const DISPLAY_NAMES=['重力翻转','弹弓投球','磁铁分球','摆锤投球','飞船停靠','卫星环游','跷板平衡','水箱调节','声波消音','滚珠平衡','弹簧运货','包裹分拣','热气球飞行','帆船进港','挖沙引水','山谷滑行','反弹投球','黏液实验','吊车装货','蹦床跳跃','穿墙小人','磁场转弯','无人机过门','液压升降台','滑轮配重','骨牌传力','冲击波回收','太空装箱','共振玻璃杯','弹簧发射器','卫星转向','电磁加速车','水轮发电站','旋转装货','漩涡收集','风扇排烟','跷板滚球','引力弹球','海浪滑板','蜘蛛人爬墙','水滴合体','冰面刹车','电梯投球','端水挑战','拧紧螺丝','营养花园','太阳帆飞行','引力接力','软糖过门','振动传送带','气罐连通','离心分球','绳索运货','双摆同步','转盘刹车','气体压缩','潜艇定深','声呐寻宝','悬索桥运输','活塞抽水'];
  const SEA_IDS=new Set([8,14,15,18,33,39,41,44,51,57,58,60]),SPACE_IDS=new Set([5,6,22,23,28,31,38,47,48]),GARDEN_IDS=new Set([2,3,4,10,11,13,16,20,27,35,37,40,46,49,53,54]),FOREST_IDS=new Set([1,7,12,19,21,24,25,26,30,34,42,45,50,55,59]);
  const HERO_IDS=new Set([1,20,21,39,40]),SHIP_IDS=new Set([5,6,22,23,31,38,47,48]),CRATE_IDS=new Set([7,11,12,19,24,25,28,34,43,53,59]);
  let visual={id:0,t:0,scene:'lab'};
  function sprite(c,key,x,y,w,h=w,a=0){F.art?.sprite?.(c,key,x,y,w,h,a);}
  function circle(c,x,y,r,col){F.circle(c,x,y,r,col);if(!F.art||r<18||r>80||String(col).length>7)return;c.save();const light=c.createRadialGradient(x-r*.35,y-r*.4,1,x,y,r);light.addColorStop(0,'#ffffff44');light.addColorStop(.55,'#ffffff00');light.addColorStop(1,'#00000055');c.fillStyle=light;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();c.restore();}
  const line=(c,a,b,d,e,col,w=3)=>F.line(c,a,b,d,e,col,w), text=(c,t,x,y,s=18,col='#e8edf5',align='left')=>F.text(c,t,x,y,s,col,align);
  function rect(c,x,y,w,h,col,r=10){F.rect(c,x,y,w,h,col,r);if(!F.art||w<18||h<16||w>880||String(col).length>7)return;c.save();c.beginPath();c.roundRect(x,y,w,h,Math.min(r,w/3,h/3));c.clip();const grad=c.createLinearGradient(x,y,x,y+h);grad.addColorStop(0,'#ffffff30');grad.addColorStop(.5,'#ffffff00');grad.addColorStop(1,'#00000055');c.fillStyle=grad;c.fillRect(x,y,w,h);c.strokeStyle='#ffffff19';c.lineWidth=1;for(let xx=x+14;xx<x+w;xx+=28){c.beginPath();c.moveTo(xx,y);c.lineTo(xx-10,y+h);c.stroke();}c.restore();if(CRATE_IDS.has(visual.id)&&w>=26&&w<=100&&h>=26&&h<=85)sprite(c,'crate',x+w/2,y+h/2,w,h);else if(w<=55&&h>110&&[1,21,23,40].includes(visual.id)){for(let yy=y+22;yy<y+h;yy+=44)sprite(c,'stone-tile',x+w/2,yy,w,44);}else if(h<=32&&w>130&&[4,7,11,19,20,24,25,37,39,42,50,59].includes(visual.id)){c.save();c.globalAlpha=.5;for(let xx=x+22;xx<x+w;xx+=44)sprite(c,'bridge',xx,y+h/2,44,h);c.restore();}}
  function ball(c,p,col='#9fe6bf',r=14){circle(c,p.x,p.y,r+6,col+'20');circle(c,p.x,p.y,r,col);circle(c,p.x-r*.25,p.y-r*.3,r*.24,'#ffffff88');if(!F.art)return;F.art.shadow?.(c,p.x,p.y+r*.9,r*.95,r*.3,.25);if([18,41].includes(visual.id)){c.save();let liquid=c.createRadialGradient(p.x-r*.35,p.y-r*.4,1,p.x,p.y,r);liquid.addColorStop(0,'#e5f9ff');liquid.addColorStop(.4,col);liquid.addColorStop(1,'#29628c');c.fillStyle=liquid;c.beginPath();c.ellipse(p.x,p.y,r*.93,r,0,0,Math.PI*2);c.fill();c.restore();return;}let key=HERO_IDS.has(visual.id)?'hero-jump':SHIP_IDS.has(visual.id)?'ship-blue':CRATE_IDS.has(visual.id)?'crate':visual.id===2?'slime':visual.id===16?'car-blue':visual.id===57?'ship-blue':[3,10,27,29,35,46,52].includes(visual.id)?'gem':'rock';sprite(c,key,p.x,p.y,Math.max(22,r*2.4),Math.max(22,r*2.4),key==='car-blue'?Math.PI/2:visual.id===57?Math.PI/2:0);}
  function ring(c,x,y,r,col='#9fe6bf',w=4){c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.strokeStyle=col;c.lineWidth=w;c.stroke();}
  function target(c,x,y,r=30){ring(c,x,y,r,'#9fe6bf');ring(c,x,y,r*.65,'#9fe6bf55');line(c,x-r-10,y,x+r+10,y,'#9fe6bf44',1);line(c,x,y-r-10,x,y+r+10,'#9fe6bf44',1);}
  function meter(c,label,v,x=80,y=480,w=300,color='#9fe6bf'){text(c,label,x,y);rect(c,x,y+12,w,12,'#ffffff15',6);rect(c,x,y+12,w*clamp(v,0,1),12,color,6);}
  function btn(c,label,x,y,w=180){F.button(c,label,x,y,w,46,'#9fe6bf');}
  const hit=(x,y,a,b,w=180,h=46)=>x>=a&&x<=a+w&&y>=b&&y<=b+h;
  const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function bounce(p,r=14){if(p.x<70+r||p.x>930-r){p.vx*=-.75;p.x=clamp(p.x,70+r,930-r);}if(p.y<135+r||p.y>465-r){p.vy*=-.75;p.y=clamp(p.y,135+r,465-r);}}
  function make(api,spec){let elapsed=0,ended=false;const g=spec;
    const finish=(win,score,msg)=>{if(!ended){ended=true;api.finish(win,Math.max(0,Math.round(Number(score)||0)),msg);}};
    g.win=(score=1000,msg='实验成功，物理引擎为你鼓掌！')=>finish(true,score,msg);g.lose=(msg='实验未达目标，再来一次就能调整方案。')=>finish(false,g.score||0,msg);g.api=api;g.t=0;g.score=0;
    return {update(dt){if(ended)return;elapsed+=dt;g.t=elapsed;if(g.tick)g.tick(Math.min(dt,.05));if(!ended&&elapsed>(g.limit||100))g.lose('时间到了，重新调整参数再试试。');api.setScore(g.score||0);},draw(c){const id=api.physicsId||0;visual={id,t:elapsed,scene:SEA_IDS.has(id)?'sea':SPACE_IDS.has(id)?'space':GARDEN_IDS.has(id)?'garden':FOREST_IDS.has(id)?'forest':'lab'};if(F.art){F.art.scene(c,visual.scene,elapsed);F.art.panel?.(c,42,110,916,367,visual.scene==='space'?'dark':'glass');c.save();c.fillStyle=visual.scene==='sea'?'#0a2f4660':visual.scene==='space'?'#07101a65':'#12251d70';c.fillRect(49,117,902,353);c.restore();F.art.panel?.(c,40,485,920,68,'dark');F.art.panel?.(c,40,562,920,40,'dark');sceneProps(c,id,elapsed);}else{F.bg(c);rect(c,42,110,916,367,'#151d2a',16);}text(c,DISPLAY_NAMES[id-1]||g.label||'PHYSICS LAB',65,88,18,'#d8f2df');text(c,Math.max(0,Math.ceil((g.limit||100)-elapsed))+'s',932,88,16,'#c5d9d0','right');if(g.paint)g.paint(c);if(F.art)sceneOver(c,id,elapsed);if(g.hint)text(c,g.hint,60,585,16,'#d3e0dc');},pointer(x,y,type){if(ended)return; if(type==='down'&&g.down)g.down(x,y);if(type==='move'&&g.move)g.move(x,y);if(type==='up'&&g.up)g.up(x,y);},key(code){if(!ended&&g.key)g.key(code);}};
  }
  function sceneProps(c,id,t){if(!F.art)return;const sea=SEA_IDS.has(id),space=SPACE_IDS.has(id);if(space){sprite(c,'turret',75,448,50);sprite(c,'ship-red',922,151,38,38,Math.sin(t*.5)*.2);for(let i=0;i<5;i++)circle(c,100+i*190,125+Math.sin(t+i)*3,2,'#8dc9ff88');}else if(sea){sprite(c,'rock',81,454,54);sprite(c,'rock',924,453,50);for(let i=0;i<6;i++){let x=70+i*172,y=453+Math.sin(t*2+i)*3;line(c,x,y,x+60,y,'#a3e7ff44',2);}}else{sprite(c,'tree',66,187,68,100);sprite(c,'tree',934,192,72,110);sprite(c,'grass-tile',95,468,70,17);sprite(c,'grass-tile',900,468,80,17);}if([7,19,24,25,32,33,37,43,50,59,60].includes(id)){sprite(c,'barrel',85,428,38,48);sprite(c,'barrel',912,428,38,48);}if([9,18,29,45,51,52,54,55,56].includes(id)){sprite(c,'turret',86,429,36);sprite(c,'turret',916,429,36);}if(id===6){c.save();c.globalAlpha=.25;sprite(c,'rock',500,305,110);c.restore();}if(id===13){sprite(c,'flag',882,430,45,70);}}
  function sceneOver(c,id,t){if(!F.art)return;if(id===13){/* balloon sprites are placed from its painted basket position below */}if(id===9){sprite(c,'turret',74,280,55,55,Math.PI/2);sprite(c,'turret',926,280,55,55,-Math.PI/2);}if(id===15){sprite(c,'barrel',117,160,46,62);sprite(c,'flag',880,425,40,60);}if(id===58){sprite(c,'castle',500,443,40,40);}if(id===59){sprite(c,'castle',105,365,68,70);sprite(c,'castle',895,365,68,70);}}
  function register(n,title,en,description,rules,controls,mechanic,build){F.register({id:'physics-'+String(n).padStart(2,'0'),title:DISPLAY_NAMES[n-1]||title,en,category:'物理游乐',color:C[(n-1)%C.length],description,rules,controls,mechanic,duration:'1–2 分钟',coverScene:SEA_IDS.has(n)?'sea':SPACE_IDS.has(n)?'space':GARDEN_IDS.has(n)?'garden':FOREST_IDS.has(n)?'forest':'lab',coverUnit:HERO_IDS.has(n)?'hero':SHIP_IDS.has(n)?'ship':'crate',create(api){let a=Object.create(api);a.physicsId=n;return build(a);}});}

  register(1,'引力换轨','GRAVITY SWITCH','让重力成为可切换的跑道。','按空格或点击翻转重力，避开上下交错障碍，到达右侧出口。碰撞会回到起点；100 秒内可重试。','空格 / 点击：反转重力','gravity polarity corridor navigation',api=>{
    let p={x:100,y:300,vy:0},sign=1;const walls=[{x:290,y:280,w:50,h:196},{x:490,y:110,w:50,h:230},{x:690,y:275,w:50,h:201}];let g;
    const flip=()=>{sign*=-1;api.sound('skill');};g={hint:'重力方向 '+(sign>0?'↓':'↑')+'  · 点击或空格切换',tick(dt){p.x+=105*dt;p.vy+=sign*480*dt;p.y+=p.vy*dt;if(p.y<148){p.y=148;p.vy=0;}if(p.y>453){p.y=453;p.vy=0;}if(walls.some(w=>p.x>w.x-12&&p.x<w.x+w.w+12&&p.y>w.y-12&&p.y<w.y+w.h+12)){p={x:100,y:300,vy:0};api.sound('hit');}if(p.x>900)g.win(1500-g.t*10);g.score=Math.round(p.x);g.hint='重力 '+(sign>0?'↓':'↑')+' · 点击 / 空格翻转 · 到达绿色出口';},paint(c){walls.forEach(w=>rect(c,w.x,w.y,w.w,w.h,'#a8b5ca'));rect(c,885,145,35,305,'#9fe6bf25');target(c,902,300,25);ball(c,p);text(c,sign>0?'↓':'↑',110,192,40,'#9fe6bf');},down:flip,key(k){if(k==='Space')flip();}};return make(api,g);
  });

  register(2,'弹性投递','ELASTIC DELIVERY','拉开弹弓，把能量变成完美抛物线。','拖拽左下光球向后蓄力，松开发射，让光球落入右侧收集环。可以重复发射。','拖拽光球：蓄力；松开：发射','slingshot vector projectile delivery',api=>{let p={x:180,y:400,vx:0,vy:0},drag=false,flying=false;let g;g={hint:'向左下拉开光球，再松手。目标：右侧收集环',down(x,y){if(!flying&&Math.hypot(x-p.x,y-p.y)<60)drag=true;},move(x,y){if(drag){p.x=clamp(x,75,260);p.y=clamp(y,280,455);}},up(){if(drag){p.vx=(180-p.x)*5;p.vy=(400-p.y)*5;flying=true;drag=false;}},tick(dt){if(flying){p.vy+=300*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(Math.hypot(p.x-790,p.y-380)<42)g.win(1600-g.t*8);if(p.x>950||p.y>490||p.x<35){p={x:180,y:400,vx:0,vy:0};flying=false;}}},paint(c){target(c,790,380,44);line(c,180,420,p.x,p.y,'#ffe58b',5);line(c,170,420,170,460,'#89765f',8);ball(c,p,'#ffe58b');if(drag){for(let t=.15;t<1.7;t+=.15){let x=p.x+(180-p.x)*5*t,y=p.y+(400-p.y)*5*t+150*t*t;if(y<465)circle(c,x,y,3,'#ffe58b66');}}}};return make(api,g);});

  register(3,'磁极分流','POLARITY SORTER','用磁场把不同电荷送进各自的舱室。','移动鼠标控制磁铁；点击切换吸引的电荷颜色。把六颗粒子引入同色左右收集区，错误入口会弹回。','移动：磁铁；点击：反转磁极','magnetic force charge-selective particle sorting',api=>{let poles=1,m={x:500,y:300},parts=Array.from({length:6},(_,i)=>({x:410+(i%3)*80,y:210+Math.floor(i/3)*100,vx:0,vy:0,q:i%2?1:-1,ok:false}));let g;g={hint:'青色粒子 → 左侧；粉色粒子 → 右侧。点击切换磁极',move(x,y){m.x=x;m.y=y;},down(){poles*=-1;},tick(dt){parts.forEach(p=>{if(p.ok)return;let dx=m.x-p.x,dy=m.y-p.y,d=Math.max(60,Math.hypot(dx,dy)),f=p.q===poles?1:-.5;p.vx=(p.vx+dx/d*180*f*dt)*.985;p.vy=(p.vy+dy/d*180*f*dt)*.985;p.x+=p.vx*dt;p.y+=p.vy*dt;bounce(p,10);if((p.q===-1&&p.x<150)||(p.q===1&&p.x>850)){p.ok=true;api.sound('hit');}});let n=parts.filter(p=>p.ok).length;g.score=n*250;if(n===6)g.win(1800-g.t*5);},paint(c){rect(c,65,138,100,315,'#8dc9ff22');rect(c,835,138,100,315,'#f4a8cf22');text(c,'−',113,310,46,'#8dc9ff');text(c,'+',880,310,46,'#f4a8cf');parts.filter(p=>!p.ok).forEach(p=>ball(c,p,p.q===-1?'#8dc9ff':'#f4a8cf',11));ring(c,m.x,m.y,40,poles===-1?'#8dc9ff':'#f4a8cf',2);text(c,poles===-1?'−':'+',m.x,m.y+7,24,'#fff','center');}};return make(api,g);});

  register(4,'摆锤脱钩','PENDULUM RELEASE','在摆动的瞬间释放，借惯性越过深谷。','摆锤自动摆动，点击或按空格断开绳索，让球进入右侧绿色区域。落空后会自动重新挂绳。','点击 / 空格：释放摆锤','pendulum tangent velocity release capture',api=>{let a=-1,t=0,p=null,reset=0;let g;const release=()=>{if(p)return;let angle=Math.sin(t*1.8)*1.05,omega=Math.cos(t*1.8)*1.89;p={x:330+180*Math.sin(angle),y:155+180*Math.cos(angle),vx:180*Math.cos(angle)*omega,vy:-180*Math.sin(angle)*omega};};g={hint:'在向右摆且接近最低点时松开 · 接球台在右侧',down:release,key(k){if(k==='Space')release();},tick(dt){t+=dt;if(p){p.vy+=280*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x>670&&p.x<880&&p.y>385&&p.y<432)g.win(1500-g.t*6);if(p.y>480||p.x<50||p.x>950){p=null;t=-.5;}}},paint(c){rect(c,670,420,210,28,'#9fe6bf');text(c,'接球区',775,405,18,'#9fe6bf','center');if(p)ball(c,p,'#ffc48d');else{a=Math.sin(t*1.8)*1.05;let x=330+180*Math.sin(a),y=155+180*Math.cos(a);line(c,330,155,x,y,'#aab6c8',3);circle(c,330,155,8,'#aab6c8');ball(c,{x,y},'#ffc48d',20);}}};return make(api,g);});

  register(5,'微推力对接','SOFT DOCK','速度和位置，都得刚刚好。','方向键或 WASD 控制小飞船推力。在绿色对接环内把速度降到 35 以下，稳定 1.5 秒。边缘会弹回。','方向键 / WASD：四向推进','inertial thruster docking with velocity constraint',api=>{let p={x:180,y:350,vx:0,vy:0},hold=0;let g;g={hint:'轻点推力并反向刹车，低速停在右上对接环内',tick(dt){const k=api.keys;p.vx+=((k.ArrowRight||k.KeyD?1:0)-(k.ArrowLeft||k.KeyA?1:0))*180*dt;p.vy+=((k.ArrowDown||k.KeyS?1:0)-(k.ArrowUp||k.KeyW?1:0))*180*dt;p.vx*=Math.pow(.8,dt);p.vy*=Math.pow(.8,dt);p.x+=p.vx*dt;p.y+=p.vy*dt;bounce(p);let speed=Math.hypot(p.vx,p.vy);hold=distance(p,{x:780,y:230})<48&&speed<35?hold+dt:0;g.score=Math.round(hold*600);if(hold>1.5)g.win(1800-g.t*8);g.hint='速度 '+Math.round(speed)+' / 35 · 对接稳定 '+hold.toFixed(1)+' / 1.5 秒';},paint(c){target(c,780,230,54);ring(c,780,230,63,'#ffffff22');ball(c,p,'#8dc9ff',17);line(c,p.x,p.y,p.x+p.vx*.2,p.y+p.vy*.2,'#8dc9ff77',2);meter(c,'对接进度',hold/1.5);}};return make(api,g);});

  register(6,'捕获轨道','ORBIT INSERTION','不用着陆，学会绕着星球飞。','拖动左侧切向速度滑块，点击发射。让探测器在引力下绕星球转过一整圈；撞击星球或飞出边界会重置。','拖动滑块；点击发射','central inverse-square orbital insertion',api=>{let v=170,p=null,angle=0,last=0;let g;g={hint:'轨道参考速度约 190 · 一周才算捕获成功',down(x,y){if(y>490&&y<540&&x>=120&&x<=440)v=110+clamp((x-120)/300,0,1)*150;else if(!p){p={x:500,y:175,vx:v,vy:0};angle=0;last=-Math.PI/2;}},move(x,y){if(api.pointer.down&&y>490&&x>=120&&x<=440)v=110+clamp((x-120)/300,0,1)*150;},tick(dt){if(!p)return;let dx=500-p.x,dy=305-p.y,d=Math.hypot(dx,dy);p.vx+=dx/d*4500000/(d*d)*dt;p.vy+=dy/d*4500000/(d*d)*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;let a=Math.atan2(p.y-305,p.x-500),delta=a-last;if(delta<-Math.PI)delta+=2*Math.PI;if(delta>Math.PI)delta-=2*Math.PI;angle+=Math.abs(delta);last=a;g.score=angle*200;if(angle>Math.PI*2)g.win(1500-g.t*5);if(d<60||p.x<55||p.x>945||p.y<118||p.y>470)p=null;},paint(c){circle(c,500,305,50,'#588a95');ring(c,500,305,130,'#8dc9ff33',1);if(p)ball(c,p,'#ffe58b',9);else ball(c,{x:500,y:175},'#ffe58b',9);meter(c,'切向速度 '+Math.round(v), (v-110)/150,120,502,300);btn(c,p?'飞行中':'点击发射',650,501);text(c,'已绕行 '+Math.round(angle*180/Math.PI)+'°',690,192,18);}};return make(api,g);});

  register(7,'动态配重','BALLAST BRIDGE','不断变化的载荷，需要恰当的力矩。','按左右方向键移动蓝色配重，使桥面倾角保持在绿色范围内累计 12 秒。货物会缓慢移动。','← / →：移动配重','moving-load seesaw torque stabilization',api=>{let x=760,a=0,vel=0,stable=0;let g;g={hint:'左右移动蓝色配重，让力矩抵消橙色货物',tick(dt){x=clamp(x+((api.keys.ArrowRight?1:0)-(api.keys.ArrowLeft?1:0))*150*dt,200,800);let cargo=650+90*Math.sin(g.t*.5),torque=(x-500)*1.4+(cargo-500);vel+=(torque*.0005-a*2-vel*2)*dt;a=clamp(a+vel*dt,-.45,.45);stable=Math.abs(a)<.065?stable+dt:Math.max(0,stable-dt*.7);g.score=stable*100;if(stable>12)g.win(1600-g.t*5);},paint(c){F.poly(c,[[475,430],[525,430],[500,345]],'#aab6c8');c.save();c.translate(500,330);c.rotate(a);rect(c,-330,0,660,16,'#b6c4d8',4);rect(c,x-520,-35,40,35,'#8dc9ff');rect(c,650+90*Math.sin(g.t*.5)-520,-35,40,35,'#ffc48d');c.restore();text(c,'倾角 '+(a*180/Math.PI).toFixed(1)+'°',100,185);meter(c,'稳定时间 '+stable.toFixed(1)+' / 12s',stable/12);}};return make(api,g);});

  register(8,'精密液闸','SLUICE CONTROL','让液位恰好够用，多一点也不行。','按住左侧进水阀加水，按住右侧排水阀放水。保持液位在两条绿线之间 8 秒，泵的压力会波动。','按住进水 / 排水按钮','water inflow-outflow tank setpoint regulation',api=>{let level=.2,mode=0,stable=0;let g;g={hint:'目标液位 55%–65% · 按住阀门控制',down(x,y){mode=hit(x,y,190,495)?1:hit(x,y,620,495)?-1:0;},up(){mode=0;},tick(dt){level=clamp(level+((mode===1?.15+.05*Math.sin(g.t*2):0)-(mode===-1?.18:0)-.013)*dt,0,1);stable=level>.55&&level<.65?stable+dt:Math.max(0,stable-dt);g.score=stable*150;if(stable>8)g.win(1600-g.t*6);},paint(c){rect(c,350,155,300,290,'#ffffff15');rect(c,357,438-level*276,286,level*276,'#8dc9ff77');line(c,340,438-.55*276,660,438-.55*276,'#9fe6bf',2);line(c,340,438-.65*276,660,438-.65*276,'#9fe6bf',2);text(c,Math.round(level*100)+'%',500,240,36,'#fff','center');btn(c,'按住：进水',190,495);btn(c,'按住：排水',620,495);text(c,'稳定 '+stable.toFixed(1)+' / 8 秒',500,465,18,'#9fe6bf','center');}};return make(api,g);});

  register(9,'相位消音','WAVE CANCELLER','两道波相遇，可以比安静更安静。','拖动相位滑块，使蓝色声波与橙色噪声反相。合成振幅小于 0.15 并保持 4 秒。','拖动：调整反相信号相位','destructive interference phase cancellation',api=>{let phase=.2,hold=0;let g;g={hint:'让两条波峰与波谷重合，绿色合成波就会接近平线',down(x,y){if(y>470)phase=clamp((x-100)/800,0,1)*Math.PI*2;},move(x,y){if(api.pointer.down&&y>470)phase=clamp((x-100)/800,0,1)*Math.PI*2;},tick(dt){let amp=Math.abs(Math.cos(phase/2))*2;hold=amp<.15?hold+dt:0;g.score=hold*300;if(hold>4)g.win(1500-g.t*5);},paint(c){for(let x=80;x<920;x+=4){let a=(x-80)/38-g.t*3,b=a+phase;line(c,x,280+Math.sin(a)*65,x+4,280+Math.sin(a+4/38)*65,'#ffc48d',2);line(c,x,280+Math.sin(b)*65,x+4,280+Math.sin(b+4/38)*65,'#8dc9ff',2);line(c,x,280+(Math.sin(a)+Math.sin(b))*65,x+4,280+(Math.sin(a+4/38)+Math.sin(b+4/38))*65,'#9fe6bf',3);}meter(c,'相位 '+Math.round(phase*180/Math.PI)+'°',phase/(2*Math.PI),100,495,800);text(c,'消音保持 '+hold.toFixed(1)+' / 4s',500,430,20,'#9fe6bf','center');}};return make(api,g);});

  register(10,'陀螺稳台','GYRO TABLE','不断转向的重力，考验手上的稳定。','移动鼠标倾斜平台，让光球保持在中心绿圈内累计 10 秒。平台有惯性，不要过度修正。','移动鼠标：倾斜平台','two-axis tilt platform ball stabilization',api=>{let p={x:500,y:300,vx:80,vy:-40},tilt={x:0,y:0},stable=0;let g;g={hint:'鼠标在中心时平台水平 · 反向倾斜可以刹车',move(x,y){tilt={x:clamp((x-500)/250,-1,1),y:clamp((y-300)/180,-1,1)};},tick(dt){p.vx+=(tilt.x*180+20*Math.sin(g.t))*dt;p.vy+=(tilt.y*180+15*Math.cos(g.t*.8))*dt;p.vx*=Math.pow(.7,dt);p.vy*=Math.pow(.7,dt);p.x+=p.vx*dt;p.y+=p.vy*dt;bounce(p);stable=distance(p,{x:500,y:300})<65?stable+dt:Math.max(0,stable-dt*.4);g.score=stable*100;if(stable>10)g.win(1500-g.t*6);},paint(c){for(let r=65;r<230;r+=65)ring(c,500,300,r,r===65?'#9fe6bf':'#ffffff15',2);line(c,500,300,500+tilt.x*70,300+tilt.y*70,'#ffc48d',4);ball(c,p,'#8dc9ff');meter(c,'中心稳定 '+stable.toFixed(1)+' / 10s',stable/10);}};return make(api,g);});

  register(11,'弹簧牵引','SPRING TETHER','拖着有弹性的货物绕过障碍。','移动鼠标牵引弹簧末端，把货球带进右侧目标。碰到红色区域会重置；目标需低速停留 1 秒。','移动鼠标：牵引锚点','damped spring tether cargo obstacle transport',api=>{let p={x:130,y:300,vx:0,vy:0},m={x:130,y:300},hold=0;let g;g={hint:'弹簧有滞后 · 走障碍下方再进入右侧圆环',move(x,y){m={x:clamp(x,70,930),y:clamp(y,135,465)};},tick(dt){p.vx+=((m.x-p.x)*7-p.vx*3.2)*dt;p.vy+=((m.y-p.y)*7-p.vy*3.2)*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;bounce(p);if(p.x>385&&p.x<605&&p.y<340){p={x:130,y:300,vx:0,vy:0};m={x:130,y:300};api.sound('hit');}hold=distance(p,{x:830,y:225})<45&&Math.hypot(p.vx,p.vy)<45?hold+dt:0;if(hold>1)g.win(1500-g.t*5);},paint(c){rect(c,400,125,190,200,'#ee8c952f');text(c,'禁入区',495,230,20,'#f1a0ab','center');target(c,830,225,48);line(c,p.x,p.y,m.x,m.y,'#8dc9ff99',3);ring(c,m.x,m.y,10,'#8dc9ff',2);ball(c,p);}};return make(api,g);});

  register(12,'输送带调度','CONVEYOR ROUTER','旋转转盘，把包裹送往正确方向。','点击中心转盘切换出口。方形包裹去上方，圆形包裹去下方；正确送达 10 个，错误超过 4 个失败。','点击 / 空格：切换出口','conveyor moving-object shape branch routing',api=>{let dir=-1,parcels=[],spawn=0,n=0,errors=0;let g;const flip=()=>dir*=-1;g={hint:'方块 ↑ · 圆球 ↓ · 点击切换中心出口',down:flip,key(k){if(k==='Space')flip();},tick(dt){spawn-=dt;if(spawn<=0){parcels.push({x:90,y:300,shape:Math.random()<.5?0:1,branch:0});spawn=1.45;}parcels.forEach(p=>{if(!p.branch){p.x+=160*dt;if(p.x>=500)p.branch=dir;}else{p.y+=p.branch*150*dt;p.x+=110*dt;if(p.y<150||p.y>450){if((p.shape===0&&p.branch===-1)||(p.shape===1&&p.branch===1))n++;else errors++;p.dead=true;api.sound('hit');}}});parcels=parcels.filter(p=>!p.dead);g.score=n*120;if(n>=10)g.win(1800-errors*200);if(errors>=5)g.lose('出口分错了 5 次，留意包裹形状。');},paint(c){line(c,80,300,500,300,'#344456',35);line(c,500,300,620,140,'#344456',35);line(c,500,300,620,460,'#344456',35);circle(c,500,300,38,'#9fe6bf');text(c,dir<0?'↑':'↓',500,313,36,'#152027','center');parcels.forEach(p=>p.shape?ball(c,p,'#ffc48d',13):rect(c,p.x-13,p.y-13,26,26,'#8dc9ff',4));text(c,'□',650,165,36,'#8dc9ff');text(c,'○',650,450,40,'#ffc48d');text(c,'送达 '+n+' / 10 · 误分 '+errors+' / 5',720,300,18,'#fff','center');}};return make(api,g);});

  register(13,'热气球航线','THERMAL BALLOON','热量慢慢上升，风会改变航向。','按住空格或画面加热，松开冷却。利用升力穿过五个不同高度的绿圈；碰上下边界会回到上一圈。','按住空格 / 画面：加热','thermal buoyancy with delayed heat response',api=>{let p={x:110,y:350,vy:0},heat=.3,held=false,next=0;const gates=[{x:260,y:220},{x:410,y:360},{x:560,y:210},{x:710,y:340},{x:860,y:240}];let g;g={hint:'按住加热会上升，松开后逐渐冷却下降 · 穿过五圈',down(){held=true;},up(){held=false;},tick(dt){heat=clamp(heat+((held||api.keys.Space)?.7:-.48)*dt,0,1);p.vy+=(80-heat*180-p.vy*1.2)*dt;p.x+=45*dt;p.y+=p.vy*dt;let gate=gates[next];if(gate&&p.x>gate.x){if(Math.abs(p.y-gate.y)<56){next++;api.sound('hit');}else{p.x=gate.x-75;p.vy=0;}}if(p.y<155||p.y>440){p.y=clamp(p.y,155,440);p.vy=0;}g.score=next*250;if(next===5)g.win(1700-g.t*4);},paint(c){gates.forEach((a,i)=>{if(i>=next)ring(c,a.x,a.y,56,i===next?'#9fe6bf':'#ffffff22');});circle(c,p.x,p.y-15,20,'#ffc48d');if(F.art){c.save();const balloon=c.createLinearGradient(p.x-27,p.y-42,p.x+27,p.y+10);balloon.addColorStop(0,'#d05b43');balloon.addColorStop(.4,'#ffd68d');balloon.addColorStop(1,'#ce5c47');c.fillStyle=balloon;c.beginPath();c.ellipse(p.x,p.y-20,27,33,0,0,Math.PI*2);c.fill();c.strokeStyle='#ffd891';c.lineWidth=3;c.beginPath();c.ellipse(p.x,p.y-20,12,33,0,0,Math.PI*2);c.stroke();line(c,p.x-12,p.y+7,p.x-8,p.y+23,'#e9d9bd',2);line(c,p.x+12,p.y+7,p.x+8,p.y+23,'#e9d9bd',2);sprite(c,'hero',p.x,p.y+14,19,25);rect(c,p.x-12,p.y+23,24,14,'#9e693e',3);c.restore();}else rect(c,p.x-10,p.y+8,20,16,'#b9c4d6',4);meter(c,'热量',heat);}};return make(api,g);});

  register(14,'侧风航行','WIND TACTICS','帆的角度，决定你能从风里借多少力。','左右方向键调整帆角，上下方向键调整航向。在风中驶向右侧港口；避开两座礁岛。','← / →：帆角；↑ / ↓：航向','wind projection sailboat heading and sail optimization',api=>{let p={x:110,y:365,vx:0,vy:0},heading=.4,sail=.8;let g;g={hint:'右侧港口在 y=300 · 礁岛周围请调整航向',tick(dt){let k=api.keys;sail=clamp(sail+((k.ArrowRight?1:0)-(k.ArrowLeft?1:0))*dt,.1,1.5);heading=clamp(heading+((k.ArrowDown?1:0)-(k.ArrowUp?1:0))*dt,-.9,.9);let wind=.55+.18*Math.sin(g.t*.5),force=110*Math.max(.1,Math.cos(sail-wind))*Math.sin(sail+.2);p.vx+=(Math.cos(heading)*force-p.vx*.6)*dt;p.vy+=(Math.sin(heading)*force-p.vy*.6)*dt;p.x+=p.vx*dt;p.y=clamp(p.y+p.vy*dt,145,450);if(distance(p,{x:390,y:260})<62||distance(p,{x:650,y:390})<62){p.x-=40;p.vx=-40;api.sound('hit');}g.score=p.x;if(p.x>875&&Math.abs(p.y-300)<75)g.win(1600-g.t*6);if(p.x>930){p.x=850;p.vx=0;}},paint(c){for(let x=100;x<900;x+=65)line(c,x,230,x+25,220,'#8dc9ff22',2);circle(c,390,260,55,'#6c7f7e');circle(c,650,390,55,'#6c7f7e');rect(c,875,225,55,150,'#9fe6bf22');c.save();c.translate(p.x,p.y);c.rotate(heading);F.poly(c,[[-20,-10],[24,0],[-20,10]],'#9fe6bf');if(F.art){sprite(c,'ship-blue',0,0,62,38,Math.PI/2);F.poly(c,[[0,0],[Math.cos(sail)*35,-Math.sin(sail)*38],[-12,-25]],'#f5ead3','#927a59');}line(c,0,0,Math.cos(sail)*25,-Math.sin(sail)*25,'#fff',4);c.restore();meter(c,'帆角 '+Math.round(sail*57.3)+'°',sail/1.5);}};return make(api,g);});

  register(15,'沙丘开渠','SAND CANAL','画出一条向下的路，让颗粒找到归宿。','按住拖动擦除沙层，给顶部的 24 颗水滴挖出流向右下收集池的通道。点击放水；收集 16 颗即可。','拖拽：挖通道；空格 / 放水按钮','erasable terrain granular falling fluid routing',api=>{let cells=Array.from({length:22},()=>Array(42).fill(1)),water=[],flow=false,drag=false,got=0;for(let y=0;y<4;y++)for(let x=0;x<42;x++)cells[y][x]=0;let g;function dig(x,y){let cx=Math.floor((x-80)/20),cy=Math.floor((y-130)/15);for(let j=cy-2;j<=cy+2;j++)for(let i=cx-2;i<=cx+2;i++)if(j>=0&&j<22&&i>=0&&i<42)cells[j][i]=0;}const start=()=>{if(!flow){flow=true;water=Array.from({length:24},(_,i)=>({x:130+R(-20,20),y:138-i*4,vx:0,vy:0}));}};g={hint:'先从左上挖一条缓坡到右下，再点击「放水」',down(x,y){if(y>490){start();return;}drag=true;dig(x,y);},move(x,y){if(drag)dig(x,y);},up(){drag=false;},key(k){if(k==='Space')start();},tick(dt){if(!flow)return;water.forEach(p=>{if(p.dead)return;p.vy=Math.min(160,p.vy+300*dt);let nx=p.x+p.vx*dt,ny=p.y+p.vy*dt,cx=Math.floor((nx-80)/20),cy=Math.floor((ny-130)/15);if(cy>=0&&cy<22&&cx>=0&&cx<42&&cells[cy][cx]){p.vy=0;let row=Math.max(0,cy-1),l=cx>0&&cells[row][cx-1]===0,r=cx<41&&cells[row][cx+1]===0;p.vx=r?90:l?-90:0;p.x=clamp(p.x+p.vx*dt,85,915);}else{p.x=nx;p.y=ny;}if(p.y>450){p.dead=true;if(p.x>730)got++;}if(p.x<80||p.x>920)p.vx*=-1;});g.score=got*80;if(got>=16)g.win(1800-g.t*5);if(water.every(p=>p.dead)&&got<16)g.lose('到达收集池的水滴不足，通道需要连到右下。');},paint(c){cells.forEach((row,j)=>row.forEach((v,i)=>{if(v)rect(c,80+i*20,130+j*15,19,14,'#c8ad7255',2);}));rect(c,735,446,180,25,'#9fe6bf77');water.filter(p=>!p.dead&&p.y>130).forEach(p=>circle(c,p.x,p.y,4,'#8dc9ff'));btn(c,'放水',410,500);text(c,'已收集 '+got+' / 16',735,510,18);}};return make(api,g);});

  register(16,'动能山谷','ENERGY VALLEY','只在下坡加速，才能攒够越岭的能量。','按住空格或画面施加顺坡推力，松开保留惯性。利用山谷积累动能越过右侧高坡。','按住空格 / 画面：顺坡加速','rolling terrain potential-kinetic energy pumping',api=>{let x=120,v=0,hold=false;const ground=x=>350+65*Math.sin((x-120)/120)+.00028*(x-450)*(x-450);let g;g={hint:'下坡时加推力，上坡靠惯性 · 右侧 880m 为终点',down(){hold=true;},up(){hold=false;},tick(dt){let slope=(ground(x+1)-ground(x-1))/2;v+=(slope*160+(hold||api.keys.Space?100:0)-v*.12)*dt;x=clamp(x+v*dt,90,920);if(x<=90)v=Math.max(0,v);g.score=x;if(x>880)g.win(1500-g.t*5);},paint(c){for(let a=80;a<930;a+=5)line(c,a,ground(a),a+5,ground(a+5),'#8dc9ff',4);let y=ground(x)-15;ball(c,{x,y},'#ffe58b');target(c,890,ground(890)-30,25);meter(c,'动能 '+Math.round(v*v/100),Math.min(1,v*v/100000));}};return make(api,g);});

  register(17,'反射投影','BOUNCE GEOMETRY','安排一面可旋转反射板，改变小球的命运。','拖动下方滑块旋转反射板，然后点击发射。光球从左侧水平飞出，撞板反弹后进入上方收集环。','拖动滑块；点击发射','angle-controlled specular collision reflection',api=>{let angle=-.6,p=null;let g;const launch=()=>{if(!p)p={x:100,y:350,vx:300,vy:0,bounced:false};};g={hint:'反射角等于入射角 · 调整板角，让球射向右上',down(x,y){if(y>490&&x<600)angle=-1.25+clamp((x-100)/450,0,1)*1.5;else launch();},move(x,y){if(api.pointer.down&&y>490&&x<600)angle=-1.25+clamp((x-100)/450,0,1)*1.5;},tick(dt){if(!p)return;p.x+=p.vx*dt;p.y+=p.vy*dt;if(!p.bounced&&p.x>=480){let nx=-Math.sin(angle),ny=Math.cos(angle),dot=p.vx*nx+p.vy*ny;p.vx-=2*dot*nx;p.vy-=2*dot*ny;p.bounced=true;}if(distance(p,{x:780,y:190})<44)g.win(1500-g.t*6);if(p.x<50||p.x>950||p.y<120||p.y>470)p=null;},paint(c){target(c,780,190,45);line(c,480-85*Math.cos(angle),350-85*Math.sin(angle),480+85*Math.cos(angle),350+85*Math.sin(angle),'#d9b2ff',10);if(p)ball(c,p,'#ffe58b',10);else ball(c,{x:100,y:350},'#ffe58b',10);meter(c,'反射板角度 '+Math.round(angle*57.3)+'°',(angle+1.25)/1.5,100,505,450);btn(c,'发射光球',700,505);}};return make(api,g);});

  register(18,'黏度配方','VISCOSITY MIX','不快不慢，液滴才能准时抵达。','点击加油或加胶改变流体黏度，点击测试让液滴滑下。让三颗液滴都在 3–5 秒内穿过终点；可反复调配。','点击配料；点击测试','viscous drag coefficient calibration by travel time',api=>{let visc=2,p=null,start=0,passes=0,result='';let g;g={hint:'黏度越高，液滴越慢 · 每次测试需要用时 3–5 秒',down(x,y){if(hit(x,y,130,500))visc=Math.max(.2,visc-.4);if(hit(x,y,410,500))visc=Math.min(7,visc+.4);if(hit(x,y,690,500)&&!p){p={x:130,y:210,vx:0};start=g.t;}},tick(dt){if(!p)return;p.vx+=(230-p.vx*visc)*dt;p.x+=p.vx*dt;p.y=210+(p.x-130)*.24;if(p.x>850){let time=g.t-start;if(time>=3&&time<=5){passes++;result='合格 '+time.toFixed(2)+' 秒';api.sound('hit');}else result='用时 '+time.toFixed(2)+' 秒，请调整';p=null;if(passes>=3)g.win(1600-g.t*4);}g.score=passes*400;},paint(c){line(c,120,225,870,405,'#58687d',28);if(p)ball(c,p,'#d9b2ff',12);text(c,'黏度 '+visc.toFixed(1),130,165,24);text(c,result,500,440,20,'#9fe6bf','center');text(c,'合格 '+passes+' / 3',800,165,22);btn(c,'加油：降低黏度',130,500,210);btn(c,'加胶：提高黏度',410,500,210);btn(c,p?'测试中':'测试液滴',690,500,180);}};return make(api,g);});

  register(19,'吊装摆幅','CRANE SWAY','吊钩停住，不代表货物也停住了。','左右键移动吊车，向下键放下货物。在右侧平台上低速落下三次；货物摆动幅度越小越好。','← / →：吊车；↓ / 点击：放货','suspended crane cargo pendulum damping and release',api=>{let crane=180,cv=0,angle=.2,av=0,cargo=null,delivered=0;let g;function release(){if(!cargo)cargo={x:crane+140*Math.sin(angle),y:165+140*Math.cos(angle),vx:cv+140*Math.cos(angle)*av,vy:0};}g={hint:'右侧平台 710–890 · 先反向移动吊车抵消摆动，再放货',down:release,key(k){if(k==='ArrowDown')release();},tick(dt){let old=cv;cv=((api.keys.ArrowRight?1:0)-(api.keys.ArrowLeft?1:0))*170;crane=clamp(crane+cv*dt,100,900);av+=(-2.8*Math.sin(angle)-av*.45-(cv-old)/140)*dt;angle+=av*dt;if(cargo){cargo.vy+=260*dt;cargo.x+=cargo.vx*dt;cargo.y+=cargo.vy*dt;if(cargo.y>410){if(cargo.x>710&&cargo.x<890&&Math.abs(cargo.vx)<100){delivered++;api.sound('hit');}cargo=null;angle=.2;av=0;}if(delivered>=3)g.win(1600-g.t*5);}g.score=delivered*400;},paint(c){line(c,90,150,910,150,'#415368',12);rect(c,crane-25,140,50,30,'#8dc9ff');rect(c,710,430,180,25,'#9fe6bf');let p=cargo||{x:crane+140*Math.sin(angle),y:165+140*Math.cos(angle)};if(!cargo)line(c,crane,165,p.x,p.y,'#aab6c8',2);rect(c,p.x-18,p.y-18,36,36,'#ffc48d',5);text(c,'已送达 '+delivered+' / 3',80,510,24);}};return make(api,g);});

  register(20,'蹦床节拍','SPRING TIMING','把每一次触底，变成更高的下一跳。','光球落到弹性垫时，按空格或点击蓄能。只有接近垫面时触发才有效，连续积累高度，触碰上方能量星。','空格 / 点击：触底助推','trampoline impulse timing energy accumulation',api=>{let p={x:500,y:300,vy:0},energy=0,flash=0;let g;const pump=()=>{if(p.y>390&&p.vy>0){energy=clamp(energy+100,0,350);flash=.3;api.sound('skill');}else energy=Math.max(0,energy-30);};g={hint:'球接近垫面并正在下落时按下 · 碰到顶部星点获胜',down:pump,key(k){if(k==='Space')pump();},tick(dt){p.vy+=340*dt;p.y+=p.vy*dt;flash=Math.max(0,flash-dt);if(p.y>420){p.y=420;p.vy=-Math.max(180,Math.abs(p.vy)*.86+energy);energy=0;}if(p.y<170)g.win(1500-g.t*8);g.score=Math.max(g.score,Math.round(420-p.y)*3);},paint(c){rect(c,360,435,280,15,flash?'#9fe6bf':'#798ba7');line(c,380,450,370,470,'#798ba7',6);line(c,620,450,630,470,'#798ba7',6);target(c,500,158,24);ball(c,p,'#d9b2ff',18);meter(c,'助推储能',energy/350);}};return make(api,g);});

  register(21,'相态穿梭','PHASE MATERIAL','实心时站稳，虚化时穿墙。','左右移动光球；空格切换实体与虚化。实体会被墙挡住，虚化可穿墙但会坠落。越过两道墙并在出口恢复实体。','← / →：移动；空格 / 点击：相态','solid-ghost phase switching with gravity and support',api=>{let p={x:110,y:280,vy:0},ghost=false;let g;function flip(){ghost=!ghost;}g={hint:'虚化穿墙时会下坠，及时切回实体回到浮空轨道',down:flip,key(k){if(k==='Space')flip();},tick(dt){let old=p.x;p.x+=((api.keys.ArrowRight?1:0)-(api.keys.ArrowLeft?1:0))*145*dt;if(ghost){p.vy+=230*dt;p.y+=p.vy*dt;}else{p.vy=0;p.y+=(280-p.y)*Math.min(1,dt*6);if([350,640].some(x=>p.x>x-25&&p.x<x+45))p.x=old;}if(p.y>450){p={x:110,y:280,vy:0};ghost=false;}p.x=clamp(p.x,80,920);if(p.x>860&&!ghost&&Math.abs(p.y-280)<20)g.win(1500-g.t*5);g.score=p.x;},paint(c){line(c,80,298,920,298,'#8dc9ff55',5);[350,640].forEach(x=>rect(c,x,150,25,220,'#d9b2ff'));target(c,880,280,30);ball(c,p,ghost?'#d9b2ff55':'#9fe6bf',17);text(c,ghost?'虚化：下坠中':'实体：轨道稳定',100,510,22,ghost?'#d9b2ff':'#9fe6bf');}};return make(api,g);});

  register(22,'回旋粒子','CYCLOTRON','在圆形加速器中，用磁场弯折速度。','按住画面或空格开启磁场，使粒子转弯；松开沿切线飞行。依次穿过三个绿圈。撞边界会回到当前检查点。','按住：磁场弯转；松开：直线','Lorentz force perpendicular velocity curvature steering',api=>{let p={x:160,y:350,a:0},held=false,next=0;const gates=[{x:450,y:350},{x:700,y:200},{x:820,y:365}];let g;g={hint:'磁场开启时顺时针转弯 · 松开直线飞行 · 依次经过三个环',down(){held=true;},up(){held=false;},tick(dt){if(held||api.keys.Space)p.a+=3.2*dt;p.x+=Math.cos(p.a)*130*dt;p.y+=Math.sin(p.a)*130*dt;let a=gates[next];if(a&&distance(p,a)<44){next++;api.sound('hit');}if(next===3)g.win(1700-g.t*5);if(p.x<65||p.x>935||p.y<130||p.y>460){p={x:next?gates[next-1].x:160,y:next?gates[next-1].y:350,a:0};}g.score=next*400;},paint(c){gates.forEach((a,i)=>{if(i>=next){target(c,a.x,a.y,42);text(c,''+(i+1),a.x,a.y+7,20,'#fff','center');}});ball(c,p,'#8dc9ff',12);line(c,p.x,p.y,p.x+Math.cos(p.a)*35,p.y+Math.sin(p.a)*35,'#8dc9ff',3);}};return make(api,g);});

  register(23,'蜂群编队','SWARM FORMATION','整队通过，任何一架都不能掉队。','鼠标上下移动控制编队宽度，点击旋转编队 90°。六架无人机会向右飞行；调整形状避开障碍并到达终点。','鼠标上下：收放编队；点击：旋转','multi-agent deformable formation aperture traversal',api=>{let x=100,spread=75,rot=0;const offsets=[[-1,-1],[0,-1],[1,-1],[-1,1],[0,1],[1,1]];let g;const pts=()=>offsets.map(([a,b])=>({x:x+(rot?b:a)*spread,y:300+(rot?a:b)*spread}));g={hint:'通过窄门时收紧编队，绿色终点必须全员通过',move(mx,my){spread=clamp((my-130)/4,16,75);},down(){rot=1-rot;},tick(dt){x+=55*dt;let wall=x>320&&x<380?{top:250,bot:350}:x>610&&x<670?{top:235,bot:365}:null;if(wall&&pts().some(p=>p.y<wall.top+9||p.y>wall.bot-9)){x=wall.top===250?270:560;api.sound('hit');}g.score=x;if(x>870)g.win(1600-g.t*5);},paint(c){[350,640].forEach((a,i)=>{let top=i?235:250,bot=i?365:350;rect(c,a,125,25,top-125,'#a6b6cd');rect(c,a,bot,25,345-bot+125,'#a6b6cd');});pts().forEach(p=>{ball(c,p,'#9fe6bf',8);ring(c,p.x,p.y,15,'#9fe6bf33',1);});text(c,'编队宽度 '+Math.round(spread),80,510,22);}};return make(api,g);});

  register(24,'液压升降','HYDRAULIC LIFT','小活塞的路程，换来大平台的力量。','按住左侧泵压使货台上升，按住泄压使其下降。把货台对齐三个依次出现的侧边泊位，各保持 1.5 秒。','按住泵压 / 泄压','coupled hydraulic piston area-ratio lift positioning',api=>{let y=415,pressure=0,mode=0,hold=0,next=0;const ys=[270,365,190];let g;g={hint:'液压会缓慢消退 · 平台与侧边绿线相差 10 以内保持 1.5 秒',down(x,my){mode=hit(x,my,170,500)?1:hit(x,my,640,500)?-1:0;},up(){mode=0;},tick(dt){pressure=clamp(pressure+(mode===1?.9:mode===-1?-1.3:-.12)*dt,0,1);y=clamp(y+(45-pressure*100)*dt,165,430);hold=Math.abs(y-ys[next])<10?hold+dt:0;if(hold>1.5){next++;hold=0;api.sound('hit');if(next===3)g.win(1500-g.t*4);}g.score=next*400+hold*100;},paint(c){rect(c,200,260,70,180,'#8dc9ff22');rect(c,206,430-pressure*150,58,pressure*150,'#8dc9ff');line(c,270,440,550,440,'#8dc9ff',12);rect(c,490,y,230,15,'#a5b8cd');rect(c,575,y+15,60,425-y,'#8dc9ff66');rect(c,565,y-50,80,50,'#ffc48d');if(next<3){line(c,750,ys[next],885,ys[next],'#9fe6bf',6);text(c,'泊位 '+(next+1),790,ys[next]-18,18,'#9fe6bf');}btn(c,'按住：泵压',170,500);btn(c,'按住：泄压',640,500);text(c,'保持 '+hold.toFixed(1)+'s',430,515);}};return make(api,g);});

  register(25,'滑轮救援','PULLEY RESCUE','用配重把吊篮送到安全高度。','点击右侧配重增加或移除砝码。配重与吊篮质量之差决定加速度；把吊篮停在上方绿区 3 秒。','点击 + / −：增减配重','Atwood pulley counterweight acceleration control',api=>{let mass=3,y=390,v=0,hold=0;let g;g={hint:'吊篮质量为 5 · 加速后需要反向配重刹停',down(x,my){if(hit(x,my,650,500,100))mass=clamp(mass+1,1,9);if(hit(x,my,800,500,100))mass=clamp(mass-1,1,9);},tick(dt){v+=((5-mass)*22-v*.65)*dt;y=clamp(y+v*dt,175,430);if(y===175||y===430)v=0;hold=y>205&&y<250&&Math.abs(v)<12?hold+dt:0;g.score=hold*400;if(hold>3)g.win(1600-g.t*5);},paint(c){ring(c,500,170,35,'#8dc9ff',7);line(c,465,170,300,y,'#aab6c8');line(c,535,170,700,605-y,'#aab6c8');rect(c,260,y,80,45,'#9fe6bf');rect(c,670,605-y,60,45,'#ffc48d');rect(c,240,205,120,45,'#9fe6bf22');text(c,'吊篮 5kg',300,y+70,18,'#9fe6bf','center');text(c,'配重 '+mass+'kg',700,650-y,18,'#ffc48d','center');btn(c,'＋',650,500,100);btn(c,'−',800,500,100);text(c,'稳定 '+hold.toFixed(1)+' / 3s',90,520,22);}};return make(api,g);});

  register(26,'冲量骨牌','IMPULSE CHAIN','不是越大力越好，让冲量逐级传下去。','拖动初始冲量条并点击释放。冲量经过不同质量骨牌逐级衰减；使最后一张落下，同时不要把脆弱骨牌击碎。','拖动：冲量；点击释放','impulse transfer through heterogeneous domino mass chain',api=>{let power=110,energy=0,index=-1,timer=0,result='';const mass=[1,.75,1.3,.8,1.1,1];let g;g={hint:'骨牌启动阈值 25 · 任一骨牌冲量超过 145 会碎裂',down(x,y){if(y>490&&x<600)power=clamp((x-80)/3,50,180);if(hit(x,y,700,500)&&index<0){energy=power;index=0;timer=0;result='';}},move(x,y){if(api.pointer.down&&y>490&&x<600)power=clamp((x-80)/3,50,180);},tick(dt){if(index<0)return;timer+=dt;if(timer>.48){timer=0;if(energy/mass[index]>145){result='第 '+(index+1)+' 张过载碎裂';index=-1;return;}if(energy<25*mass[index]){result='冲量不足，停在第 '+(index+1)+' 张';index=-1;return;}energy*=.83;index++;g.score=index*200;api.sound('hit');if(index===6)g.win(1600-g.t*5);}},paint(c){mass.forEach((m,i)=>{c.save();c.translate(150+i*130,420);if(index>i)c.rotate(.95);rect(c,-12,-140*m,24,140*m,C[i],4);c.restore();text(c,m+'kg',150+i*130,455,16,'#aab6c8','center');});meter(c,'初始冲量 '+Math.round(power),(power-50)/130,80,505,500);btn(c,'释放冲量',700,505);text(c,result,500,165,20,'#ffc48d','center');}};return make(api,g);});

  register(27,'脉冲清障','PULSE SHEPHERD','一道扩散波，把碎片推向回收环。','点击产生扩散冲击波，把八片漂浮碎片推入外沿绿色回收带。波只会向外推，选择碎片内侧施放。','点击：释放径向脉冲','radial impulse field debris boundary recycling',api=>{let parts=Array.from({length:8},()=>({x:R(300,700),y:R(210,390),vx:0,vy:0,ok:false})),waves=[];let g;g={hint:'点击碎片的内侧，把它推向四周绿色回收边界',down(x,y){waves.push({x,y,r:0,hit:new Set()});api.sound('skill');},tick(dt){waves.forEach(w=>{w.r+=400*dt;parts.forEach((p,i)=>{let d=distance(p,w);if(!p.ok&&!w.hit.has(i)&&d<w.r){w.hit.add(i);let f=200;p.vx+=(p.x-w.x)/Math.max(1,d)*f;p.vy+=(p.y-w.y)/Math.max(1,d)*f;}});});waves=waves.filter(w=>w.r<500);parts.forEach(p=>{if(p.ok)return;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.45,dt);p.vy*=Math.pow(.45,dt);if(p.x<100||p.x>900||p.y<155||p.y>435)p.ok=true;});let n=parts.filter(p=>p.ok).length;g.score=n*150;if(n===8)g.win(1600-g.t*5);},paint(c){rect(c,65,135,870,25,'#9fe6bf22');rect(c,65,435,870,25,'#9fe6bf22');rect(c,65,135,35,325,'#9fe6bf22');rect(c,900,135,35,325,'#9fe6bf22');parts.filter(p=>!p.ok).forEach(p=>{F.poly(c,[[p.x,p.y-10],[p.x+12,p.y+8],[p.x-10,p.y+7]],'#ffc48d');});waves.forEach(w=>ring(c,w.x,w.y,w.r,'#8dc9ff66',2));text(c,'回收 '+parts.filter(p=>p.ok).length+' / 8',80,520,24);}};return make(api,g);});

  register(28,'零重力装箱','ZERO-G PACKING','一个轻推，会让货箱一直漂下去。','拖动货箱向目标方向甩出。把三个货箱分别停在同色目标内，点击漂移中的箱子可以制动；边界反弹。','拖拽甩出：施加冲量；点击：制动','direct impulse drag cargo with click braking in zero gravity',api=>{let boxes=[{x:180,y:220,vx:0,vy:0},{x:180,y:310,vx:0,vy:0},{x:180,y:400,vx:0,vy:0}],sel=-1,start=null,goals=[{x:780,y:210},{x:780,y:300},{x:780,y:390}],hold=0;let g;g={hint:'轻甩箱子开始移动 · 到达目标时点击箱子刹车',down(x,y){sel=boxes.findIndex(p=>Math.abs(x-p.x)<28&&Math.abs(y-p.y)<28);if(sel>=0){boxes[sel].vx=0;boxes[sel].vy=0;start={x,y};}},up(x,y){if(sel>=0&&start){boxes[sel].vx=clamp((x-start.x)*2,-250,250);boxes[sel].vy=clamp((y-start.y)*2,-250,250);}sel=-1;start=null;},tick(dt){boxes.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;bounce(p,22);});let n=boxes.filter((p,i)=>distance(p,goals[i])<37&&Math.hypot(p.vx,p.vy)<20).length;g.score=n*400;hold=n===3?hold+dt:0;if(hold>1)g.win(1600-g.t*4);},paint(c){goals.forEach((p,i)=>{ring(c,p.x,p.y,40,C[i],2);text(c,''+(i+1),p.x,p.y+7,20,C[i],'center');});boxes.forEach((p,i)=>{rect(c,p.x-20,p.y-20,40,40,C[i],6);text(c,''+(i+1),p.x,p.y+7,20,'#142332','center');});}};return make(api,g);});

  register(29,'共振调谐','RESONANCE LAB','找到频率，能量就会自己积累。','拖动频率滑块让振动器与三只杯子的自然频率依次共振。振幅到达满格可通过；离开共振区振幅会衰减。','拖动：频率调谐','driven damped resonance amplitude frequency matching',api=>{let f=2,amp=0,next=0;const natural=[3.2,5.7,4.4];let g;g={hint:'让蓝点对准当前杯子的固有频率，保持到振幅充满',down(x,y){if(y>480)f=1+clamp((x-100)/800,0,1)*6;},move(x,y){if(api.pointer.down&&y>480)f=1+clamp((x-100)/800,0,1)*6;},tick(dt){if(next>=3)return;let gain=Math.max(0,1-Math.abs(f-natural[next])*3);amp=clamp(amp+(gain>.7?gain*.3:-.25)*dt,0,1);if(amp>=1){next++;amp=0;api.sound('hit');if(next===3)g.win(1600-g.t*5);}g.score=next*400+amp*300;},paint(c){natural.forEach((a,i)=>{let x=260+i*240,shake=i===next?Math.sin(g.t*f*10)*amp*12:0;rect(c,x-45+shake,230,90,165,i<next?'#9fe6bf44':'#8dc9ff33');ring(c,x+shake,230,44,i===next?'#8dc9ff':'#ffffff33',3);text(c,a.toFixed(1)+'Hz',x,425,20,i===next?'#9fe6bf':'#aab6c8','center');});meter(c,'驱动频率 '+f.toFixed(2)+' Hz',(f-1)/6,100,500,800);meter(c,'振幅',amp,100,160,800);}};return make(api,g);});

  register(30,'压缩跃迁','COMPRESSION LEAP','给弹簧恰当的压缩量，飞过移动窗口。','按住画面或空格压缩弹簧，松开发射。让弹珠穿过右侧上下移动的窗口三次。每次会自动回到弹簧。','按住：压缩；松开：发射','spring stored-energy launch through oscillating aperture',api=>{let compression=0,held=false,p=null,n=0;let g;function release(){if(held&&!p){p={x:180,y:400,vx:250+compression*250,vy:-80-compression*200};compression=0;}held=false;}g={hint:'窗口缓慢上下移动 · 压缩越多飞得越高越快',down(){if(!p)held=true;},up:release,key(k){if(k==='Space'&&!p)held=true;},tick(dt){if(api.keys.Space&&!p)held=true;else if(held&&!api.pointer.down&&!api.keys.Space)release();if(held&&!p)compression=clamp(compression+dt*.45,0,1);if(p){p.vy+=260*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x>=790){if(Math.abs(p.y-(310+60*Math.sin(g.t*.8)))<48){n++;api.sound('hit');}p=null;}else if(p.y>470||p.y<125)p=null;}g.score=n*400;if(n>=3)g.win(1700-g.t*5);},paint(c){let gate=310+60*Math.sin(g.t*.8);rect(c,790,125,25,gate-55-125,'#aab6c8');rect(c,790,gate+55,25,470-gate-55,'#aab6c8');target(c,805,gate,43);rect(c,145,430,70,15,'#8dc9ff');for(let i=0;i<6;i++)line(c,150,415-i*(8-compression*4),210,410-i*(8-compression*4),'#8dc9ff',3);ball(c,p||{x:180,y:360+compression*35},'#ffe58b');meter(c,'压缩储能',compression);text(c,'通过 '+n+' / 3',730,520,24);}};return make(api,g);});

  register(31,'反作用轮','REACTION WHEEL','没有空气，也能靠角动量转身。','左右方向键对内部飞轮施加扭矩，使外壳角度对齐依次出现的目标箭头。角误差小于 8°且角速度足够小时保持 1 秒。','← / →：飞轮扭矩','angular momentum reaction wheel attitude stabilization',api=>{let a=0,v=0,next=0,hold=0;const angles=[Math.PI/2,-Math.PI/2,Math.PI];let g;const wrap=a=>Math.atan2(Math.sin(a),Math.cos(a));g={hint:'提前反向施加扭矩刹车 · 无阻力转动不会自己停止',tick(dt){v+=((api.keys.ArrowLeft?1:0)-(api.keys.ArrowRight?1:0))*1.8*dt;v*=Math.pow(.93,dt);a=wrap(a+v*dt);let error=Math.abs(wrap(a-angles[next]));hold=error<.14&&Math.abs(v)<.15?hold+dt:0;if(hold>1){next++;hold=0;api.sound('hit');if(next===3)g.win(1800-g.t*5);}g.score=next*400+hold*200;},paint(c){ring(c,500,300,110,'#8dc9ff44',2);if(next<3){let goal=angles[next];line(c,500,300,500+Math.cos(goal)*145,300+Math.sin(goal)*145,'#9fe6bf88',7);}c.save();c.translate(500,300);c.rotate(a);rect(c,-80,-32,160,64,'#a8b7d0');F.poly(c,[[100,0],[65,-25],[65,25]],'#8dc9ff');circle(c,0,0,22,'#172332');c.restore();text(c,'角速度 '+v.toFixed(2)+' rad/s',100,510,22);text(c,'目标 '+(next+1)+' / 3',740,510,22);}};return make(api,g);});

  register(32,'感应加速轨','INDUCTION RAIL','磁场要在正确的时间开和关。','按住空格或画面开启线圈。球在中心线左侧时被加速，越过线圈中心后会被拉回。让球以 160–260 的速度进入末端缓冲站。','按住：线圈通电；松开：断电','position-timed solenoid acceleration and terminal velocity gating',api=>{let p={x:120,v:70},held=false;const coils=[280,470,660];let g;g={hint:'接近线圈时通电，经过中心立刻断电 · 末速目标 160–260',down(){held=true;},up(){held=false;},tick(dt){if(held||api.keys.Space)coils.forEach(x=>{let d=x-p.x;if(Math.abs(d)<100)p.v+=Math.sign(d)*220*dt;});p.v-=12*dt;p.x+=p.v*dt;if(p.x<90||p.v<3){p={x:120,v:70};}if(p.x>870){if(p.v>=160&&p.v<=260)g.win(1500-g.t*5);else{p={x:120,v:70};api.sound('hit');}}g.score=Math.max(g.score,p.x);},paint(c){line(c,90,320,910,320,'#64748b',6);coils.forEach(x=>{rect(c,x-36,260,72,120,held||api.keys.Space?'#8dc9ff55':'#8dc9ff15');line(c,x,250,x,390,'#8dc9ff66',2);});rect(c,850,260,65,120,'#9fe6bf33');ball(c,{x:p.x,y:320},'#ffe58b',13);text(c,'当前速度 '+Math.round(p.v)+'  ·  目标 160–260',100,510,23);}};return make(api,g);});

  register(33,'水轮发电','HYDRO TURBINE','水流能发电，转得太快也会过载。','拖动开度控制水闸。保持水轮转速在绿色区间累计发出 100 单位电；转速超过红线会损失能量。','拖动滑块：水闸开度','hydraulic turbine angular acceleration and safe operating power',api=>{let valve=.3,rpm=0,angle=0,power=0;let g;g={hint:'理想转速 60–90 · 超过 110 会过载 · 闸门响应存在惯性',down(x,y){if(y>480)valve=clamp((x-100)/800,0,1);},move(x,y){if(api.pointer.down&&y>480)valve=clamp((x-100)/800,0,1);},tick(dt){rpm+=(valve*(160+25*Math.sin(g.t*.6))-rpm)*dt*.6;angle+=rpm*.02*dt;if(rpm>=60&&rpm<=90)power+=6*dt;if(rpm>110)power=Math.max(0,power-dt*10);g.score=power*10;if(power>=100)g.win(1700-g.t*4);},paint(c){ring(c,500,300,95,'#8dc9ff',5);for(let i=0;i<8;i++){let a=angle+i*Math.PI/4;line(c,500,300,500+Math.cos(a)*90,300+Math.sin(a)*90,'#9fe6bf',11);}for(let i=0;i<valve*20;i++)circle(c,300+Math.sin(i+g.t*3)*15,150+(i*28+g.t*100)%270,3,'#8dc9ff');text(c,'转速 '+Math.round(rpm),730,260,28,rpm>110?'#f1a0ab':'#8dc9ff');text(c,'储能 '+Math.round(power)+' / 100',730,310,22);meter(c,'水闸开度 '+Math.round(valve*100)+'%',valve,100,500,800);}};return make(api,g);});

  register(34,'旋转货舱','SHAPE DOCK','把不规则货物转到适合洞口的角度。','左右方向键旋转长条货物，按空格投送。依次通过三个角度不同的窄口；误差需小于 9°。','← / →：转货；空格 / 点击：投送','rigid-body orientation aperture matching',api=>{let angle=0,next=0,push=0,result='';const goals=[-.65,.8,.2];let g;function send(){if(next>=3||push)return;let d=Math.abs(Math.atan2(Math.sin(angle-goals[next]),Math.cos(angle-goals[next])));if(d<.16){push=1;result='方向匹配';}else{result='角度不匹配，请继续旋转';api.sound('hit');}}g={hint:'货物与绿色开口保持平行后投送 · 不是横竖方块配对',down:send,key(k){if(k==='Space')send();},tick(dt){angle+=((api.keys.ArrowRight?1:0)-(api.keys.ArrowLeft?1:0))*1.2*dt;if(push){push+=dt*2;if(push>2){next++;push=0;api.sound('hit');if(next===3)g.win(1500-g.t*5);}}g.score=next*400;},paint(c){if(next<3){c.save();c.translate(720,300);c.rotate(goals[next]);rect(c,-12,-105,24,210,'#9fe6bf22');rect(c,-70,-22,140,44,'#9fe6bf33');line(c,-70,-28,70,-28,'#9fe6bf',4);line(c,-70,28,70,28,'#9fe6bf',4);c.restore();}c.save();c.translate(260+(push?clamp(push-1,0,1)*460:0),300);c.rotate(angle);rect(c,-63,-17,126,34,'#ffc48d');c.restore();text(c,result,500,465,20,'#9fe6bf','center');text(c,'完成 '+next+' / 3',80,520,23);}};return make(api,g);});

  register(35,'涡流收纳','VORTEX CATCHER','用旋转流场把漂浮粒子卷进核心。','按住鼠标创建吸入涡流。移动涡心收集 18 颗漂浮粒子；粒子进入核心时速度过快会被甩出。','按住并移动：涡心位置','spiral tangential flow plus damped radial particle capture',api=>{let m={x:500,y:300},held=false,parts=Array.from({length:18},()=>({x:R(110,890),y:R(165,435),vx:0,vy:0,ok:false}));let g;g={hint:'缓慢移动涡心，给粒子时间减速收拢',down(x,y){held=true;m={x,y};},move(x,y){m={x:clamp(x,100,900),y:clamp(y,160,440)};},up(){held=false;},tick(dt){parts.forEach(p=>{if(p.ok)return;let dx=m.x-p.x,dy=m.y-p.y,d=Math.max(1,Math.hypot(dx,dy));if(held){p.vx+=(dx*.85-dy*.22-p.vx*2.5)*dt;p.vy+=(dy*.85+dx*.22-p.vy*2.5)*dt;}p.x+=p.vx*dt;p.y+=p.vy*dt;bounce(p,7);if(held&&d<22&&Math.hypot(p.vx,p.vy)<80){p.ok=true;api.sound('hit');}});let n=parts.filter(p=>p.ok).length;g.score=n*70;if(n===18)g.win(1700-g.t*5);},paint(c){if(held){for(let r=25;r<150;r+=25)ring(c,m.x,m.y,r,'#d9b2ff22',2);circle(c,m.x,m.y,17,'#d9b2ff');}parts.filter(p=>!p.ok).forEach(p=>ball(c,p,'#8dc9ff',6));text(c,'已收集 '+parts.filter(p=>p.ok).length+' / 18',80,520,23);}};return make(api,g);});

  register(36,'烟雾通风','SMOKE FLOW','转动风扇，让烟粒绕过挡板找到出口。','点击两个风扇依次切换右、下、左、上风向。把 16 个烟粒中的 10 个送入右上绿色排气口；画面持续补充烟粒。','点击风扇：旋转风向','local fan vector field smoke advection around baffles',api=>{let fans=[{x:300,y:350,a:0},{x:660,y:330,a:0}],parts=[],spawn=0,got=0;let g;g={hint:'第一台向右、第二台向上可以形成转弯气流 · 点风扇调整',down(x,y){fans.forEach(f=>{if(Math.hypot(x-f.x,y-f.y)<60)f.a+=Math.PI/2;});},tick(dt){spawn-=dt;if(spawn<0){parts.push({x:115,y:350+R(-20,20),vx:25,vy:0});spawn=.6;}parts.forEach(p=>{fans.forEach(f=>{let d=distance(p,f);if(d<300){p.vx+=(Math.cos(f.a)*110*(1-d/350))*dt;p.vy+=(Math.sin(f.a)*110*(1-d/350))*dt;}});p.vx*=Math.pow(.7,dt);p.vy*=Math.pow(.7,dt);p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x>450&&p.x<480&&p.y<290){p.x=448;p.vx=0;}if(p.x>730&&p.y<190){got++;p.dead=true;api.sound('hit');}if(p.x>945||p.x<65||p.y<130||p.y>465)p.dead=true;});parts=parts.filter(p=>!p.dead).slice(-60);g.score=got*120;if(got>=10)g.win(1700-g.t*4);},paint(c){rect(c,450,125,30,165,'#8395ad');rect(c,730,130,190,60,'#9fe6bf22');text(c,'排气口',820,170,20,'#9fe6bf','center');fans.forEach(f=>{ring(c,f.x,f.y,40,'#8dc9ff',2);line(c,f.x,f.y,f.x+Math.cos(f.a)*38,f.y+Math.sin(f.a)*38,'#8dc9ff',5);});parts.forEach(p=>circle(c,p.x,p.y,5,'#d9e2ed77'));text(c,'排出 '+got+' / 10',80,520,23);}};return make(api,g);});

  register(37,'质量交换','MASS SWAP','同一副跷板，换质量就换方向。','点击左右两个物体在轻、重质量间切换。通过改变力矩让滚珠沿跷板向右滚入收集槽；必须控制倾角避免掉出。','点击配重：轻重切换','discrete mass toggling torque-driven ball slope traversal',api=>{let masses=[1,1],angle=0,av=0,p={x:-220,v:0};let g;g={hint:'左侧重会左低，右侧重会右低 · 让滚珠缓慢滚向右边',down(x,y){if(Math.hypot(x-240,y-260)<70)masses[0]=3-masses[0];if(Math.hypot(x-760,y-260)<70)masses[1]=3-masses[1];},tick(dt){av+=((masses[1]-masses[0])*.8-angle*3-av*2)*dt;angle=clamp(angle+av*dt,-.35,.35);p.v+=(Math.sin(angle)*220-p.v*.12)*dt;p.x+=p.v*dt;if(p.x<-310){p={x:-220,v:0};}if(p.x>290&&Math.abs(p.v)<200)g.win(1500-g.t*5);if(p.x>320)p={x:-220,v:0};g.score=p.x+300;},paint(c){F.poly(c,[[480,450],[520,450],[500,365]],'#7e90a9');c.save();c.translate(500,350);c.rotate(angle);rect(c,-320,0,640,14,'#b7c5d8');ball(c,{x:p.x,y:-15},'#9fe6bf',13);c.restore();[240,760].forEach((x,i)=>{rect(c,x-35,230,70,60,masses[i]===2?'#ffc48d':'#8dc9ff');text(c,masses[i]===2?'重':'轻',x,267,22,'#152332','center');});target(c,810,400,27);}};return make(api,g);});

  register(38,'引力透镜','GRAVITY LENS','移动一颗小行星，让航线弯出一条捷径。','拖动紫色引力源，点击发射探测器。引力会让原本直线的轨迹弯折；让探测器到达右下目标，撞上引力源会重置。','拖动：引力源；点击发射','movable inverse-distance lens projectile deflection',api=>{let source={x:520,y:340},drag=false,p=null;let g;g={hint:'把引力源放在直线路径下方，吸引探测器朝右下弯折',down(x,y){if(distance({x,y},source)<55)drag=true;else if(y>490&&!p)p={x:100,y:240,vx:240,vy:0};},move(x,y){if(drag&&!p)source={x:clamp(x,280,740),y:clamp(y,170,440)};},up(){drag=false;},tick(dt){if(!p)return;let dx=source.x-p.x,dy=source.y-p.y,d=Math.max(20,Math.hypot(dx,dy)),f=2500000/(d*d);p.vx+=dx/d*f*dt;p.vy+=dy/d*f*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(distance(p,{x:860,y:390})<46)g.win(1600-g.t*5);if(d<28||p.x<60||p.x>940||p.y<125||p.y>470)p=null;},paint(c){for(let r=45;r<160;r+=35)ring(c,source.x,source.y,r,'#d9b2ff22',1);ball(c,source,'#d9b2ff',23);target(c,860,390,45);ball(c,p||{x:100,y:240},'#8dc9ff',10);btn(c,p?'探测中':'发射探测器',400,500,210);}};return make(api,g);});

  register(39,'潮汐踏浪','TIDE SURFER','踩在不断移动的波峰上。','左右键沿波面移动滑板，按空格跳起收集浮标。收集六枚高处浮标；不同位置的波峰会随时间传播。','← / →：移动；空格：跃起','travelling wave surface support with jump buoy collection',api=>{let p={x:100,y:330,vy:0,air:false},buoys=Array.from({length:6},(_,i)=>({x:210+i*125,y:225+(i%2)*25,ok:false}));const wave=(x,t)=>365+42*Math.sin(x/80-t*2);let g;const jump=()=>{if(!p.air){p.air=true;p.vy=-260;}};g={hint:'乘着波峰接近浮标后跳起 · 六个浮标都要拿到',key(k){if(k==='Space')jump();},down:jump,tick(dt){p.x=clamp(p.x+((api.keys.ArrowRight?1:0)-(api.keys.ArrowLeft?1:0))*155*dt,80,920);if(p.air){p.vy+=420*dt;p.y+=p.vy*dt;if(p.y>wave(p.x,g.t)-15&&p.vy>0){p.air=false;p.vy=0;p.y=wave(p.x,g.t)-15;}}else p.y=wave(p.x,g.t)-15;buoys.forEach(b=>{if(!b.ok&&distance(p,b)<30){b.ok=true;api.sound('hit');}});let n=buoys.filter(b=>b.ok).length;g.score=n*200;if(n===6)g.win(1700-g.t*5);},paint(c){for(let x=70;x<930;x+=5)line(c,x,wave(x,g.t),x+5,wave(x+5,g.t),'#8dc9ff',4);buoys.filter(b=>!b.ok).forEach(b=>ball(c,b,'#ffe58b',10));rect(c,p.x-25,p.y+7,50,8,'#9fe6bf',4);ball(c,p,'#9fe6bf',11);text(c,'浮标 '+buoys.filter(b=>b.ok).length+' / 6',80,520,23);}};return make(api,g);});

  register(40,'黏附攀升','WALL ADHESION','松开这一侧，再抓住另一侧。','按住左右方向键吸附对应墙壁，空格蹬墙跳。交替利用两壁向上攀升，到达顶部出口；没有吸附时会坠落。','← / →：吸附；空格：蹬墙','alternating adhesion wall jumps against gravity',api=>{let p={x:350,y:420,vx:0,vy:0},side=-1,height=0;let g;const jump=()=>{if(side){p.vx=-side*240;p.vy=-260;side=0;}};g={hint:'左墙按 ←，右墙按 → · 抓住墙后按空格蹬到对面',key(k){if(k==='Space')jump();},down:jump,tick(dt){if(!side){p.vy+=310*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(p.x<360&&api.keys.ArrowLeft){p.x=350;side=-1;p.vx=0;p.vy=-40;}if(p.x>640&&api.keys.ArrowRight){p.x=650;side=1;p.vx=0;p.vy=-40;}}else{p.vy=0;if((side<0&&!api.keys.ArrowLeft)||(side>0&&!api.keys.ArrowRight)){side=0;p.vy=0;}}if(p.y>435){p.y=435;p.vy=0;p.vx=0;if(p.x<400)side=-1;else if(p.x>600)side=1;}height=Math.max(height,435-p.y);g.score=height*4;if(p.y<155)g.win(1500-g.t*5);p.x=clamp(p.x,350,650);},paint(c){rect(c,300,125,35,335,'#64758b');rect(c,665,125,35,335,'#64758b');rect(c,335,125,330,30,'#9fe6bf33');ball(c,p,'#9fe6bf',14);text(c,'攀升 '+Math.round(height)+' / 280',80,520,23);}};return make(api,g);});

  register(41,'动量合滴','MOMENTUM MERGE','两滴相遇，速度由质量决定。','拖拽左侧液滴选择发射方向与速度，松开发射。与右侧缓慢漂移液滴合并后，让合滴进入下方目标；合并遵守动量守恒。','拖拽液滴：甩出；点击重置按钮','inelastic liquid collision mass-weighted momentum conservation',api=>{let a,b,drag=false,start=null,merged=false,active=false;function reset(){a={x:180,y:240,vx:0,vy:0,m:1};b={x:650,y:300,vx:-30,vy:25,m:2};merged=false;active=false;}reset();let g;g={hint:'蓝滴质量 1，紫滴质量 2 · 合滴速度会偏向紫滴',down(x,y){if(y>490){reset();return;}if(distance(a,{x,y})<35&&!merged){drag=true;start={x,y};}},up(x,y){if(drag){a.vx=clamp((x-start.x)*3,-350,350);a.vy=clamp((y-start.y)*3,-250,250);active=true;}drag=false;},tick(dt){if(!active)return;[a,b].forEach(p=>{if(!p)return;p.x+=p.vx*dt;p.y+=p.vy*dt;bounce(p,merged?23:16);});if(b&&distance(a,b)<34){a.vx=(a.vx+2*b.vx)/3;a.vy=(a.vy+2*b.vy)/3;a.x=(a.x+2*b.x)/3;a.y=(a.y+2*b.y)/3;b=null;merged=true;api.sound('skill');}if(merged&&distance(a,{x:720,y:415})<48)g.win(1600-g.t*5);},paint(c){target(c,720,415,46);ball(c,a,merged?'#9fe6bf':'#8dc9ff',merged?23:16);if(b)ball(c,b,'#d9b2ff',21);btn(c,'重新配滴',400,500,200);if(drag)line(c,a.x,a.y,api.pointer.x,api.pointer.y,'#8dc9ff',2);}};return make(api,g);});

  register(42,'热轨滑行','THERMAL FRICTION','在冰面画热区，让滑块自己停准。','拖动在轨道上画加热区，然后点击发车。滑块经过热区会增加摩擦；让它停在右侧 760–850 的绿色区域。可清空重试。','拖拽：画热区；发车 / 清空按钮','painted spatial friction field stopping-distance control',api=>{let zones=[],p=null,draw=false;let g;g={hint:'加热区会慢慢刹车 · 过早画太长会停不到目标',down(x,y){if(hit(x,y,650,500)){if(!p)p={x:110,v:340};}else if(hit(x,y,100,500)){zones=[];p=null;}else if(y>220&&y<420){draw=true;zones.push({x:clamp(x,100,900),w:42});}},move(x,y){if(draw&&y>220&&y<420)zones.push({x:clamp(x,100,900),w:42});},up(){draw=false;},tick(dt){if(!p)return;let heated=zones.some(z=>Math.abs(p.x-z.x)<z.w/2);p.v=Math.max(0,p.v-(heated?200:4)*dt);p.x+=p.v*dt;if(p.v<1){if(p.x>=760&&p.x<=850)g.win(1500-g.t*4);else{g.hint='停在 '+Math.round(p.x)+'，点击清空后调整热区';p=null;}}if(p&&p.x>925){p=null;g.hint='刹车不足，点击清空后增加加热区';}},paint(c){rect(c,90,290,830,65,'#8dc9ff22');zones.forEach(z=>rect(c,z.x-z.w/2,290,z.w,65,'#ffc48d44',0));rect(c,760,290,90,65,'#9fe6bf33',0);if(p)rect(c,p.x-18,295,36,40,'#d9b2ff');text(c,'760–850',805,390,20,'#9fe6bf','center');btn(c,'清空并重置',100,500,210);btn(c,'发车',650,500,210);}};return make(api,g);});

  register(43,'升降机惯性','ELEVATOR INERTIA','电梯停得越急，货物跳得越高。','按住空格或画面让电梯加速上升，松开立即制动。货球保留向上的惯性，飞入上方绿色货舱；完成三次。','按住：电梯上行；松开：紧急制动','accelerating elevator stop inertial object separation',api=>{let y=425,v=0,held=false,p=null,n=0;let g;function stop(){if(held&&!p){p={y:y-20,v};v=0;}held=false;}g={hint:'在货舱正下方蓄积向上速度，再松开电梯制动',down(){if(!p)held=true;},up:stop,key(k){if(k==='Space'&&!p)held=true;},tick(dt){if(api.keys.Space&&!p)held=true;else if(held&&!api.pointer.down&&!api.keys.Space)stop();if(held&&!p){v-=220*dt;y+=v*dt;if(y<220){y=220;stop();}}if(p){p.v+=300*dt;p.y+=p.v*dt;if(p.y<190&&p.y>140){n++;p=null;y=425;v=0;api.sound('hit');}else if(p.y>450){p=null;y=425;v=0;}if(n>=3)g.win(1600-g.t*5);}g.score=n*400;},paint(c){line(c,380,130,380,460,'#52647b',5);line(c,620,130,620,460,'#52647b',5);rect(c,395,y,210,18,'#8dc9ff');rect(c,420,140,160,50,'#9fe6bf22');text(c,'惯性货舱',500,168,18,'#9fe6bf','center');ball(c,{x:500,y:p?p.y:y-20},'#ffe58b',16);text(c,'已投递 '+n+' / 3',80,520,23);}};return make(api,g);});

  register(44,'液面平衡','SLOSH BALANCE','端着会晃的水，稳稳走完整条路。','鼠标水平移动带着容器向右走，液面会因加速度倾斜。把容器送到右侧终点，剩余水量至少 65%；过快甩动会洒水。','鼠标水平移动：搬运容器','container acceleration liquid slosh and spill preservation',api=>{let x=120,targetX=120,v=0,tilt=0,tv=0,water=1;let g;g={hint:'缓慢匀速移动，急停和加速都会让水晃出来',move(mx){targetX=clamp(mx,120,880);},tick(dt){let old=v;v+=(targetX-x)*5*dt;v*=Math.pow(.05,dt);x+=v*dt;let accel=(v-old)/Math.max(.01,dt);tv+=(-tilt*9-tv*2-accel*.003)*dt;tilt+=tv*dt;if(Math.abs(tilt)>.32)water=Math.max(0,water-(Math.abs(tilt)-.32)*dt*.8);g.score=water*1000;if(water<.65)g.lose('水洒得太多了，放慢加速和刹车再试。');if(x>860&&Math.abs(v)<25&&water>=.65)g.win(1000+water*600-g.t*3);},paint(c){line(c,100,405,910,405,'#53647a',4);rect(c,850,210,65,195,'#9fe6bf11');rect(c,x-55,290,110,110,'#8dc9ff22');let left=385-water*75+tilt*70,right=385-water*75-tilt*70;F.poly(c,[[x-48,left],[x+48,right],[x+48,393],[x-48,393]],'#8dc9ff99');meter(c,'剩余水量 '+Math.round(water*100)+'%',water);text(c,'终点',880,235,18,'#9fe6bf','center');}};return make(api,g);});

  register(45,'精密扭矩','TORQUE LIMITER','拧紧刚刚好，多一点就滑牙。','按住按钮增加当前螺栓的扭矩，松开锁定。把四颗螺栓都锁在各自绿色区间；超过红线会重置当前螺栓。','按住：施加扭矩；松开：锁定','elastic torsion accumulation and per-bolt preload window',api=>{let torque=0,held=false,next=0,angle=0;const ranges=[[.38,.52],[.62,.76],[.25,.4],[.7,.86]];let g;function release(){if(!held)return;held=false;let a=ranges[next];if(torque>=a[0]&&torque<=a[1]){next++;api.sound('hit');if(next===4)g.win(1700-g.t*4);}torque=0;}g={hint:'绿色区间随螺栓变化 · 松开才会锁定，不要一直按住',down(){held=true;},up:release,tick(dt){if(held){torque+=dt*(.22+.08*Math.sin(g.t*2));angle+=dt*3;if(torque>1){torque=0;held=false;api.sound('hit');}}g.score=next*300;},paint(c){for(let i=0;i<4;i++){let x=220+i*185;ring(c,x,290,38,i<next?'#9fe6bf':i===next?'#8dc9ff':'#ffffff33',10);line(c,x-16,290,x+16,290,'#aab6c8',4);}if(next<4){let a=ranges[next];rect(c,100,417,800,25,'#ffffff15');rect(c,100+a[0]*800,417,(a[1]-a[0])*800,25,'#9fe6bf66');rect(c,100,417,torque*800,25,'#8dc9ff66');line(c,100+torque*800,408,100+torque*800,452,'#fff',3);}text(c,'扭矩 '+Math.round(torque*100)+' Nm',500,500,24,'#fff','center');}};return make(api,g);});

  register(46,'扩散花园','DIFFUSION GARDEN','给浓度一点引导，颜色会沿着梯度生长。','按住拖动向池中注入营养，营养会向相邻格扩散并缓慢衰减。让三个绿色培养皿同时达到 0.45 以上浓度，保持 3 秒。','按住拖动：注入营养','discrete diffusion equation concentration field target coverage',api=>{const w=20,h=8;let field=Array(w*h).fill(0),held=false,m={x:500,y:300},hold=0;const targets=[{x:4,y:2},{x:10,y:5},{x:16,y:2}];let g;function feed(){let x=Math.floor((m.x-100)/40),y=Math.floor((m.y-150)/36);if(x>=0&&x<w&&y>=0&&y<h)field[y*w+x]=1;}g={hint:'不断补充三个培养皿周围的浓度，扩散会填满相邻格',down(x,y){held=true;m={x,y};feed();},move(x,y){m={x,y};},up(){held=false;},tick(dt){if(held)feed();let next=field.slice();for(let y=0;y<h;y++)for(let x=0;x<w;x++){let i=y*w+x,v=field[i],sum=0,n=0;[[1,0],[-1,0],[0,1],[0,-1]].forEach(([a,b])=>{if(x+a>=0&&x+a<w&&y+b>=0&&y+b<h){sum+=field[(y+b)*w+x+a];n++;}});next[i]=clamp(v+((sum-n*v)*.35-v*.018)*dt,0,1);}field=next;let min=Math.min(...targets.map(t=>field[t.y*w+t.x]));hold=min>.45?hold+dt:0;g.score=hold*300;if(hold>3)g.win(1600-g.t*4);},paint(c){field.forEach((v,i)=>rect(c,100+(i%w)*40,150+Math.floor(i/w)*36,38,34,'rgba(157,218,255,'+(.06+v*.94)+')',4));targets.forEach(t=>{let v=field[t.y*w+t.x];ring(c,119+t.x*40,167+t.y*36,16,'#9fe6bf',3);text(c,Math.round(v*100)+'%',120+t.x*40,163+t.y*36,11,'#fff','center');});meter(c,'培养稳定 '+hold.toFixed(1)+' / 3s',hold/3);}};return make(api,g);});

  register(47,'太阳帆巡航','SOLAR SAIL','借太阳光压，慢慢改变轨道高度。','左右方向键旋转太阳帆。帆面对太阳时增大轨道半径，背向时减小；把探测器送入目标轨道带并保持 6 秒。','← / →：太阳帆角度','solar radiation sail incidence orbital radius drift',api=>{let radius=90,rv=0,angle=0,orbit=0,hold=0;let g;g={hint:'帆角余弦决定光压 · 半径目标 150–175 · 接近时转帆刹住',tick(dt){angle+=((api.keys.ArrowRight?1:0)-(api.keys.ArrowLeft?1:0))*1.7*dt;rv+=(Math.cos(angle)*12-rv*.7)*dt;radius=clamp(radius+rv*dt,75,190);orbit+=dt*.65;hold=radius>=150&&radius<=175?hold+dt:0;g.score=hold*200;if(hold>6)g.win(1600-g.t*4);},paint(c){circle(c,500,300,40,'#ffe58b');ring(c,500,300,150,'#9fe6bf44',2);ring(c,500,300,175,'#9fe6bf44',2);let x=500+Math.cos(orbit)*radius,y=300+Math.sin(orbit)*radius;c.save();c.translate(x,y);c.rotate(angle+orbit);rect(c,-6,-30,12,60,'#d9b2ff');c.restore();ball(c,{x,y},'#8dc9ff',8);text(c,'轨道半径 '+Math.round(radius),90,510,22);text(c,'保持 '+hold.toFixed(1)+' / 6s',650,510,22);}};return make(api,g);});

  register(48,'引力接力','WELL RELAY','只点亮一颗引力井，交替接住小球。','点击三个引力井切换唯一激活井。把小球依次带到三个井附近，最后停留在最右井 2 秒；引力不会立即消除惯性。','点击引力井：切换激活','one-hot switched gravity attractors sequential handoff',api=>{let wells=[{x:260,y:225},{x:500,y:380},{x:780,y:230}],active=0,next=0,p={x:110,y:300,vx:0,vy:0},hold=0;let g;g={hint:'靠近当前目标井后，再点击下一颗井 · 末井需要低速停稳',down(x,y){let i=wells.findIndex(w=>distance(w,{x,y})<65);if(i>=0)active=i;},tick(dt){let a=wells[active];p.vx+=((a.x-p.x)*2-p.vx*2.4)*dt;p.vy+=((a.y-p.y)*2-p.vy*2.4)*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;bounce(p);if(next<3&&distance(p,wells[next])<35){next++;api.sound('hit');}hold=next===3&&distance(p,wells[2])<35&&Math.hypot(p.vx,p.vy)<25?hold+dt:0;g.score=next*350+hold*100;if(hold>2)g.win(1600-g.t*4);},paint(c){wells.forEach((a,i)=>{ring(c,a.x,a.y,48,i===active?'#d9b2ff':'#ffffff22',3);circle(c,a.x,a.y,12,i<next?'#9fe6bf':'#d9b2ff');text(c,''+(i+1),a.x,a.y+6,16,'#152332','center');});ball(c,p,'#ffe58b',12);text(c,'接力 '+next+' / 3 · 末井停留 '+hold.toFixed(1)+'s',80,520,23);}};return make(api,g);});

  register(49,'等面积变形','MORPHIC PASSAGE','面积不能变，形状可以。','上下方向键改变软体的高宽比，保持面积不变。自动前进穿过三种轮廓不同的孔道，碰撞后回到上一处。','↑：变高；↓：变宽','constant-area aspect-ratio deformable aperture navigation',api=>{let x=110,ratio=1,next=0;const gates=[{x:330,w:100,h:42},{x:580,w:38,h:120},{x:820,w:68,h:70}];let g;g={hint:'总面积 3600 不变 · 先扁、再高、最后接近正方形',tick(dt){ratio=clamp(ratio+((api.keys.ArrowUp?1:0)-(api.keys.ArrowDown?1:0))*dt*2,.22,4);let w=Math.sqrt(3600/ratio),h=3600/w;x+=48*dt;let a=gates[next];if(a&&Math.abs(x-a.x)<15){if(w>a.w||h>a.h){x=a.x-85;api.sound('hit');}else{next++;x=a.x+25;api.sound('hit');}}g.score=next*400;if(next===3&&x>875)g.win(1600-g.t*4);},paint(c){gates.forEach((a,i)=>{if(i<next)return;rect(c,a.x-13,125,26,175-a.h/2,'#8294ad');rect(c,a.x-13,300+a.h/2,26,170-a.h/2,'#8294ad');text(c,a.w+'×'+a.h,a.x,180,16,'#aab6c8','center');});let w=Math.sqrt(3600/ratio),h=3600/w;rect(c,x-w/2,300-h/2,w,h,'#d9b2ff',16);text(c,'形状 '+Math.round(w)+' × '+Math.round(h),80,520,23);}};return make(api,g);});

  register(50,'振动输送','VIBRO TRANSPORT','正确的振动，能让零件单向滑行。','拖动振动频率，让零件沿台面向右运输。频率 3–5Hz 时产生有效摩擦整流，过快会让零件反向回滑；运完五件。','拖动滑块：振动频率','asymmetric vibration friction rectification transport',api=>{let frequency=1.5,items=Array.from({length:5},(_,i)=>({x:110+i*60,v:0,done:false}));let g;g={hint:'找出能持续向右走的频段 · 观察台面振动和零件速度',down(x,y){if(y>490)frequency=.5+clamp((x-100)/800,0,1)*7;},move(x,y){if(api.pointer.down&&y>490)frequency=.5+clamp((x-100)/800,0,1)*7;},tick(dt){let drive=frequency>=3&&frequency<=5?65:frequency>5?-35:0;items.forEach(p=>{if(p.done)return;p.v+=(drive-p.v)*dt*2;p.x+=p.v*dt;if(p.x>880){p.done=true;api.sound('hit');}p.x=Math.max(90,p.x);});let n=items.filter(p=>p.done).length;g.score=n*250;if(n===5)g.win(1600-g.t*4);},paint(c){let yy=360+Math.sin(g.t*frequency*6.28)*7;rect(c,90,yy,820,22,'#8395ae');items.filter(p=>!p.done).forEach((p,i)=>rect(c,p.x-14,yy-30,28,30,C[i],4));for(let x=120;x<880;x+=90)F.poly(c,[[x,yy+40],[x+15,yy+22],[x+30,yy+40]],'#53647b');meter(c,'振动频率 '+frequency.toFixed(1)+'Hz',(frequency-.5)/7,100,505,800);text(c,'送达 '+items.filter(p=>p.done).length+' / 5',100,185,24);}};return make(api,g);});

  register(51,'压力均衡','PRESSURE NETWORK','三个气舱，只有压差会推动气流。','点击管道阀门开关，让初始不等的三舱压力趋于均衡。三舱压力均在 45–55 之间并保持 5 秒成功。','点击两段阀门：开关气路','coupled pressure differential valve equilibration',api=>{let pressure=[90,10,50],open=[false,false],hold=0;let g;g={hint:'阀门打开后，高压舱会向低压舱缓慢流动',down(x,y){if(Math.hypot(x-350,y-300)<70)open[0]=!open[0];if(Math.hypot(x-650,y-300)<70)open[1]=!open[1];},tick(dt){for(let i=0;i<2;i++)if(open[i]){let flow=(pressure[i]-pressure[i+1])*.55*dt;pressure[i]-=flow;pressure[i+1]+=flow;}hold=pressure.every(p=>p>=45&&p<=55)?hold+dt:0;g.score=hold*250;if(hold>5)g.win(1500-g.t*4);},paint(c){[200,500,800].forEach((x,i)=>{rect(c,x-65,200,130,200,'#8dc9ff22');rect(c,x-60,394-pressure[i]*1.85,120,pressure[i]*1.85,'#8dc9ff77');text(c,pressure[i].toFixed(1),x,185,23,'#fff','center');});[350,650].forEach((x,i)=>{line(c,x-85,300,x+85,300,'#6f819a',15);circle(c,x,300,30,open[i]?'#9fe6bf':'#f1a0ab');text(c,open[i]?'开':'关',x,308,20,'#152332','center');});meter(c,'均衡保持 '+hold.toFixed(1)+' / 5s',hold/5);}};return make(api,g);});

  register(52,'离心分离','CENTRIFUGE','密度不同，向外迁移的速度就不同。','拖动转速使重粒子进入外圈、轻粒子留在内圈。五颗重粒子半径超过 110、五颗轻粒子半径小于 85 时保持 2 秒。','拖动：离心机转速','density-dependent radial centrifuge separation',api=>{let speed=.2,particles=Array.from({length:10},(_,i)=>({r:50+(i%5)*4,a:i*Math.PI/5,heavy:i<5})),hold=0;let g;g={hint:'蓝色是轻粒子，橙色是重粒子 · 分离后降低转速保持',down(x,y){if(y>490)speed=clamp((x-100)/800,0,1);},move(x,y){if(api.pointer.down&&y>490)speed=clamp((x-100)/800,0,1);},tick(dt){particles.forEach(p=>{p.a+=(speed*7+.4)*dt;let outward=speed*speed*(p.heavy?52:14),returning=(p.r-50)*.1;p.r=clamp(p.r+(outward-returning)*dt,45,155);});let valid=particles.every(p=>p.heavy?p.r>110:p.r<85);hold=valid?hold+dt:0;g.score=hold*500;if(hold>2)g.win(1600-g.t*4);},paint(c){ring(c,500,300,160,'#8dc9ff44',3);ring(c,500,300,110,'#ffc48d55',2);ring(c,500,300,85,'#8dc9ff55',2);particles.forEach(p=>ball(c,{x:500+Math.cos(p.a)*p.r,y:300+Math.sin(p.a)*p.r},p.heavy?'#ffc48d':'#8dc9ff',8));meter(c,'离心转速 '+Math.round(speed*100)+'%',speed,100,505,800);text(c,'分离保持 '+hold.toFixed(1)+' / 2s',80,185,22);}};return make(api,g);});

  register(53,'张力走线','CABLE TENSION','绳子可以拉，却不能无限拉。','移动鼠标拉动缆索锚点，牵引货物通过三个检查点。缆索拉长超过红色阈值持续 0.6 秒会断裂并回到起点。','鼠标移动：缆索锚点','unilateral cable tension limit sequential cargo waypoints',api=>{let p={x:140,y:350,vx:0,vy:0},anchor={x:140,y:300},next=0,over=0;const goals=[{x:350,y:200},{x:580,y:380},{x:820,y:230}];let g;g={hint:'慢慢拖动锚点 · 绳长 80 以内安全，拉到 160 以上会断裂',move(x,y){anchor={x:clamp(x,70,930),y:clamp(y,140,450)};},tick(dt){let dx=anchor.x-p.x,dy=anchor.y-p.y,d=Math.max(1,Math.hypot(dx,dy)),force=Math.max(0,d-55)*6;p.vx+=(dx/d*force-p.vx*3)*dt;p.vy+=(dy/d*force+35-p.vy*3)*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;bounce(p);over=d>160?over+dt:0;if(over>.6){p={x:140,y:350,vx:0,vy:0};anchor={x:140,y:300};next=0;over=0;api.sound('hit');}if(next<3&&distance(p,goals[next])<35){next++;api.sound('hit');}g.score=next*400;if(next===3)g.win(1600-g.t*4);},paint(c){goals.forEach((a,i)=>{if(i>=next)target(c,a.x,a.y,35);});let d=distance(p,anchor);line(c,p.x,p.y,anchor.x,anchor.y,d>160?'#f1a0ab':'#8dc9ff',3);ring(c,anchor.x,anchor.y,10,'#8dc9ff',2);ball(c,p,'#ffc48d',16);meter(c,'缆索张力',d/160,80,510,400,d>160?'#f1a0ab':'#8dc9ff');}};return make(api,g);});

  register(54,'双摆同步','COUPLED OSCILLATORS','两只摆，各有自己的节奏。','按住画面或空格开启耦合弹簧，让两只摆同步。松开时两摆会按自己的频率继续摆动；相位差小于 0.12 保持 6 秒。','按住：耦合；松开：自由振动','coupled phase oscillator synchronization',api=>{let a=0,b=2.5,held=false,hold=0;let g;g={hint:'耦合会拉近两只摆的相位 · 连续同步 6 秒即可',down(){held=true;},up(){held=false;},tick(dt){let delta=Math.atan2(Math.sin(b-a),Math.cos(b-a)),couple=held||api.keys.Space?2.5:0;a+=(1.7+couple*Math.sin(delta))*dt;b+=(2-couple*Math.sin(delta))*dt;let error=Math.abs(Math.atan2(Math.sin(b-a),Math.cos(b-a)));hold=error<.12?hold+dt:0;g.score=hold*220;if(hold>6)g.win(1600-g.t*4);},paint(c){let x1=300+110*Math.sin(a),y1=170+170*Math.cos(Math.sin(a)*.7),x2=700+110*Math.sin(b),y2=170+170*Math.cos(Math.sin(b)*.7);line(c,300,150,x1,y1,'#8dc9ff',3);line(c,700,150,x2,y2,'#d9b2ff',3);ball(c,{x:x1,y:y1},'#8dc9ff',19);ball(c,{x:x2,y:y2},'#d9b2ff',19);if(held||api.keys.Space)line(c,x1,y1,x2,y2,'#9fe6bf66',2);meter(c,'相位同步 '+hold.toFixed(1)+' / 6s',hold/6);}};return make(api,g);});

  register(55,'惯性刻度','INERTIAL DIAL','松开刹车转动，压住刹车停准。','按住画面或空格对转盘制动，松开电机会逐渐加速。依次让指针对准三段绿色刻度，速度低于阈值后自动锁定。','按住：摩擦制动；松开：电机加速','one-direction motor friction braking sequential angle locking',api=>{let a=0,v=.6,next=0,hold=0;const targets=[1.7,4.4,2.8];let held=false,g;g={hint:'提前刹车 · 指针只顺时针旋转 · 三个刻度依次锁定',down(){held=true;},up(){held=false;},tick(dt){v=clamp(v+((held||api.keys.Space)?-3:.55)*dt,0,2.4);a=(a+v*dt)%(Math.PI*2);let e=next<3?Math.abs(Math.atan2(Math.sin(a-targets[next]),Math.cos(a-targets[next]))):0;hold=e<.16&&v<.12?hold+dt:0;if(hold>.8){next++;hold=0;api.sound('hit');if(next===3)g.win(1700-g.t*4);}g.score=next*450;},paint(c){ring(c,500,300,120,'#8dc9ff44',5);for(let i=0;i<24;i++){let t=i*Math.PI/12;line(c,500+Math.cos(t)*110,300+Math.sin(t)*110,500+Math.cos(t)*120,300+Math.sin(t)*120,'#aab6c8',2);}if(next<3){let t=targets[next];circle(c,500+Math.cos(t)*120,300+Math.sin(t)*120,18,'#9fe6bf44');}line(c,500,300,500+Math.cos(a)*105,300+Math.sin(a)*105,'#ffe58b',6);text(c,'转速 '+v.toFixed(2),80,510,22);text(c,'刻度 '+next+' / 3',740,510,22);}};return make(api,g);});

  register(56,'气体状态','GAS WORKSHOP','温度、体积、压力，彼此都在悄悄联动。','左右键改变活塞体积，上下键加热或降温。把气体压力调到 1.8–2.2、温度调到 1.4–1.6，同时保持 4 秒。','← / →：体积；↑ / ↓：温度','ideal gas pressure-volume-temperature simultaneous constraint control',api=>{let volume=1.5,temp=1,hold=0;let g;g={hint:'压力 = 温度 / 体积 · 先调温度，再压缩活塞',tick(dt){let k=api.keys;volume=clamp(volume+((k.ArrowRight?1:0)-(k.ArrowLeft?1:0))*.5*dt,.4,2);temp=clamp(temp+((k.ArrowUp?1:0)-(k.ArrowDown?1:0))*.4*dt,.5,2);let pressure=temp/volume;hold=pressure>1.8&&pressure<2.2&&temp>1.4&&temp<1.6?hold+dt:0;g.score=hold*300;if(hold>4)g.win(1600-g.t*4);},paint(c){let w=volume*260;rect(c,160,180,540,240,'#8dc9ff11');rect(c,160,180,w,240,'#ffc48d22');rect(c,160+w,175,18,250,'#a8b8cf');for(let i=0;i<26;i++){let x=170+((i*79+g.t*(35+i%5*10))%Math.max(20,w-20)),y=195+((i*47+g.t*31)%210);circle(c,x,y,4,temp>1.5?'#ffc48d':'#8dc9ff');}text(c,'P '+(temp/volume).toFixed(2),770,230,25);text(c,'V '+volume.toFixed(2),770,280,25);text(c,'T '+temp.toFixed(2),770,330,25);meter(c,'稳定 '+hold.toFixed(1)+' / 4s',hold/4);}};return make(api,g);});

  register(57,'压舱深潜','BALLAST DEPTH','把潜艇停在水里，而不是停在海底。','按住左侧按钮注水增加重量，按住右侧按钮排水增加浮力。把潜艇停在绿色深度带 8 秒；水流会缓慢变化。','按住注水 / 排水','variable ballast submarine buoyancy equilibrium under current',api=>{let y=210,v=0,ballast=.35,mode=0,hold=0;let g;g={hint:'目标深度 305–345 · 提前排水刹住下潜速度',down(x,my){mode=hit(x,my,160,500)?1:hit(x,my,650,500)?-1:0;},up(){mode=0;},tick(dt){ballast=clamp(ballast+mode*.22*dt,0,1);v+=((ballast-.5)*100+5*Math.sin(g.t*.8)-v*.9)*dt;y=clamp(y+v*dt,170,440);if(y===170||y===440)v=0;hold=y>305&&y<345?hold+dt:0;g.score=hold*160;if(hold>8)g.win(1700-g.t*4);},paint(c){rect(c,70,305,860,40,'#9fe6bf15',0);line(c,70,305,930,305,'#9fe6bf66',1);line(c,70,345,930,345,'#9fe6bf66',1);rect(c,430,y-20,140,40,'#8dc9ff',20);circle(c,530,y,9,'#172332');line(c,465,y-20,465,y-36,'#8dc9ff',7);meter(c,'压舱水 '+Math.round(ballast*100)+'%',ballast,90,155,250);btn(c,'按住：注水下潜',160,500,220);btn(c,'按住：排水上浮',650,500,220);text(c,'深度保持 '+hold.toFixed(1)+'s',730,200,20,'#9fe6bf');}};return make(api,g);});

  register(58,'声呐定位','ECHO MAPPING','听不见的距离，可以用回声画出来。','点击「发射声呐」，三座固定声源的回声距离环会显示交点；点击画面标记隐藏信标的位置，误差小于 24 即成功。可反复探测。','点击声呐；点击地图：标记','trilateration from acoustic echo distance circles',api=>{const beacon={x:R(370,650),y:R(220,370)},sources=[{x:190,y:210},{x:800,y:210},{x:500,y:420}];let ping=false,wave=0,mark=null;let g;g={hint:'三个回声圆交于同一点，那就是信标 · 先发声呐再标记',down(x,y){if(y>490){ping=true;wave=0;api.sound('skill');}else if(ping){mark={x,y};let d=distance(mark,beacon);g.score=Math.max(0,1000-d*5);if(d<24)g.win(1800-g.t*4);else g.hint='标记误差 '+Math.round(d)+'，再观察三个回声圆的交点';}},tick(dt){if(ping)wave=Math.min(600,wave+180*dt);},paint(c){sources.forEach((s,i)=>{circle(c,s.x,s.y,9,C[i]);text(c,'声源 '+(i+1),s.x,s.y-20,15,C[i],'center');if(ping){let d=distance(s,beacon);ring(c,s.x,s.y,Math.min(wave,d),C[i]+'88',2);if(wave>=d)text(c,Math.round(d)+'m',s.x,s.y+30,15,C[i],'center');}});if(mark){line(c,mark.x-10,mark.y,mark.x+10,mark.y,'#fff',2);line(c,mark.x,mark.y-10,mark.x,mark.y+10,'#fff',2);}btn(c,'发射声呐',390,500,220);}};return make(api,g);});

  register(59,'悬索承载','CABLE STRUCTURE','把有限的张力，分配给正在过桥的载荷。','点击三根悬索切换松、紧两档。载荷从左向右移动时，拉紧附近悬索承重；同时拉紧超过两根会超出总预算。送过四辆货车。','点击悬索：松紧切换','moving-load suspension cable stress allocation budget',api=>{let cables=[false,false,false],truck=110,passed=0,stress=0;let g;g={hint:'货车附近需要一根拉紧悬索 · 最多同时拉紧两根',down(x,y){[280,500,720].forEach((a,i)=>{if(Math.abs(x-a)<75&&y>170&&y<440)cables[i]=!cables[i];});},tick(dt){truck+=55*dt;let nearest=Math.round((truck-280)/220);nearest=clamp(nearest,0,2);let covered=truck<190||truck>820||cables[nearest],count=cables.filter(Boolean).length;stress=clamp(stress+((!covered||count>2)?dt*.8:-dt*.6),0,1);if(stress>=1){g.lose('桥梁应力超过承载，提前拉紧货车附近的悬索。');return;}if(truck>900){passed++;truck=110;api.sound('hit');if(passed>=4)g.win(1800-g.t*4);}g.score=passed*300;},paint(c){line(c,100,400,900,400,stress>.5?'#f1a0ab':'#a8bad0',8);[280,500,720].forEach((x,i)=>{line(c,x,160,x,400,cables[i]?'#9fe6bf':'#53647b',cables[i]?7:3);circle(c,x,165,12,'#aab6c8');text(c,cables[i]?'拉紧':'松弛',x,220,17,cables[i]?'#9fe6bf':'#97a6b8','center');});rect(c,truck-25,365,50,30,'#ffc48d',5);circle(c,truck-14,398,7,'#aab6c8');circle(c,truck+14,398,7,'#aab6c8');meter(c,'结构应力',stress,80,505,420,stress>.5?'#f1a0ab':'#9fe6bf');text(c,'通过 '+passed+' / 4',750,520,23);}};return make(api,g);});

  register(60,'往复泵站','RECIPROCATING PUMP','进水和出水，得踩对活塞的半个周期。','左右键手动移动活塞。向右拉时点击切为进水阀，向左推时切为出水阀；正确行程把水送入储罐，累计 100 单位完成。','← / →：活塞；空格 / 点击：切换阀门','reciprocating piston check-valve phase-coordinated fluid pumping',api=>{let x=300,mode=0,water=0,chamber=0;let g;const toggle=()=>mode=1-mode;g={hint:'右拉＋进水阀，左推＋出水阀 · 按空格切阀，循环抽水',down:toggle,key(k){if(k==='Space')toggle();},tick(dt){let dir=(api.keys.ArrowRight?1:0)-(api.keys.ArrowLeft?1:0),old=x;x=clamp(x+dir*160*dt,220,560);let delta=x-old;if(delta>0&&mode===0)chamber=clamp(chamber+delta*.12,0,45);if(delta<0&&mode===1){let pumped=Math.min(chamber,-delta*.12);water+=pumped;chamber-=pumped;}if(delta<0&&mode===0)chamber=Math.max(0,chamber+delta*.1);g.score=water*12;if(water>=100)g.win(1700-g.t*4);},paint(c){rect(c,180,220,420,130,'#8dc9ff22');rect(c,190,230,Math.max(0,x-200),110,'#8dc9ff44');rect(c,x,215,15,140,'#aab6c8');line(c,x+15,285,650,285,'#aab6c8',9);rect(c,735,180,150,260,'#8dc9ff15');rect(c,741,434-Math.min(100,water)*2.4,138,Math.min(100,water)*2.4,'#8dc9ff77');circle(c,390,390,28,mode===0?'#9fe6bf':'#ffc48d');text(c,mode===0?'进水阀':'出水阀',390,450,22,mode===0?'#9fe6bf':'#ffc48d','center');text(c,'储罐 '+Math.round(water)+' / 100',810,160,20,'#9fe6bf','center');text(c,'泵腔 '+Math.round(chamber),220,190,20);meter(c,'输送完成',water/100);}};return make(api,g);});
})();
